const S={route:'home',docs:[],doc:null,pages:[],p:1,ann:[],knowledge:[],cards:[],reviews:[],analytics:null,messages:[],settings:{},auth:null,promptSettings:null,modelProviders:[],modelConfigs:[],availableModels:[],activeModelId:'',selection:'',selectionLatex:'',tab:'Chat',search:'',zoom:100,conversationId:'',learningSessionId:'',learningSessionDocumentId:'',learningCourses:[],learningDocuments:[],learningCoursesLoading:false,quizItems:[],quizAnswers:[],quizTopic:'',pendingPrompt:null,pendingPromptOverride:null};
const NAV=[['home','⌂','Home'],['library','▤','Library'],['courses','▦','Courses'],['reading','◉','Reading'],['chat','✦','AI Chat'],['knowledge','◇','Knowledge'],['notes','▱','Notes'],['review','↻','Review'],['analytics','⌁','Learning Analytics'],['account','◎','Account'],['settings','⚙','Settings']];
const esc=x=>String(x??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const api=async(u,o={})=>{const r=await fetch(u,{headers:{'Content-Type':'application/json'},...o}),d=await r.json();if(!r.ok)throw Error(d.error?.message||'Request failed');return d};
const title=()=>({home:'Home',library:'Library',courses:'Courses',reading:'Reading',chat:'AI Chat',knowledge:'Knowledge',notes:'Notes',review:'Review',analytics:'Learning Analytics',account:'Account',settings:'Settings'})[S.route]||'Home';
function toast(x){const e=document.createElement('div');e.className='toast';e.textContent=x;document.getElementById('toast-root').append(e);setTimeout(()=>e.remove(),2400)}
const AVATAR_PALETTE=['#635bff','#e58b47','#2f9e8f','#b45ad6','#3d82c4','#d65f7a','#8a6d3b','#5b7a3f','#3f6d8a','#a34f6d'];
function hashString(value){let hash=0;for(const ch of String(value||''))hash=(hash*31+ch.codePointAt(0))|0;return Math.abs(hash)}
function firstChar(value){const ch=[...String(value||'')][0]||'S';return ch.codePointAt(0)>0x2E7F?ch:ch.toUpperCase()}
function avatar(){const en=uiLanguage()==='en';const user=S.auth?.user;const guest=!S.auth||S.auth.guest===true||!user;const label=user?.username||'Guest';if(guest)return `<button type="button" class="avatar avatar-guest" title="${en?'Guest mode — click to sign in':'游客模式 · 点击登录'}" onclick="go('account')"><span>◌</span><span class="avatar-label">${en?'Guest':'游客'}</span></button>`;const color=AVATAR_PALETTE[hashString(user.id||user.email||label)%AVATAR_PALETTE.length];return `<button type="button" class="avatar" title="${esc(label)} · ${en?'Account':'账号'}" onclick="go('account')" style="background:${color}"><span>${esc(firstChar(label))}</span><span class="avatar-label">${en?'Signed in':'已登录'}</span></button>`}
function homeGreeting(){const user=S.auth?.user;const guest=!S.auth||S.auth.guest===true||!user;const en=uiLanguage()==='en';const hour=new Date().getHours();const period=hour<12?'morning':hour<18?'afternoon':'evening';return {name:guest?(en?'':''):String(user.username||''),title:guest?(en?'Start your learning session.':(period==='morning'?'早上好':period==='afternoon'?'下午好':'晚上好')):(en?`Good ${period}, ${user.username}.`:`${period==='morning'?'早上好':period==='afternoon'?'下午好':'晚上好'}，${user.username}。`),subtitle:guest?(en?'Sign in from the avatar in the top right to keep your data account-scoped.':'点击右上角头像登录个人账号，学习数据会按账号隔离保存。'):(en?'Turn today’s reading into durable knowledge.':'将今天的阅读转化为长期知识。')}}
function homeDateLabel(){const en=uiLanguage()==='en';const now=new Date();const day=en?now.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}):now.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});return en?`${day} · Learning streak 6 days`:`${day} · 连续学习 6 天`}
function frame(body){document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">S</div><div><strong>StudyAgent</strong><small>AI LEARNING WORKSPACE</small></div></div><nav class="nav"><div class="nav-label">Workspace</div>${NAV.map(([id,ic,l])=>`<button class="${S.route===id?'active':''}" onclick="go('${id}')"><span>${ic}</span><span>${l}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="mode-pill"><i class="dot"></i> Local-first mode</div><div>Your learning data stays on this device.</div></div></aside><main class="main"><div class="topbar"><div class="crumb">Workspace / <strong>${title()}</strong></div><div class="top-actions"><div class="search">⌕ <input value="${esc(S.search)}" placeholder="Search library..." onkeydown="if(event.key==='Enter'){S.search=this.value;go('library')}" /></div><button class="icon-btn" onclick="command()">⌘</button><button class="icon-btn" onclick="toast('暂无新的通知')">♢</button>${avatar()}</div></div>${body}</main></div>`}
function go(x,id){S.route=x;if(id){const previous=S.doc?.id;S.doc=S.docs.find(d=>d.id===id)||S.doc;if(previous!==S.doc?.id)S.conversationId='';S.route='reading';loadReader()}else render()}
async function render(){try{if(!S.docs.length)S.docs=await api('/api/documents');if(!S.ann.length)S.ann=await api('/api/annotations');if(!S.knowledge.length){const k=await api('/api/knowledge');S.knowledge=k.points;S.cards=k.cards}if(!S.reviews.length)S.reviews=await api('/api/review/today');if(!S.analytics)S.analytics=await api('/api/analytics');if(!S.modelProviders.length){const p=await api('/api/models/providers');S.modelProviders=p.providers||[]}if(!S.modelConfigs.length){const m=await api('/api/models/configs');S.modelConfigs=m.configs||[];S.activeModelId=m.defaultId||''}if(!S.messages.length||!Object.keys(S.settings).length){const a=await api('/api/state');S.messages=a.messages||[];S.settings=a.settings||{}}if(S.route==='reading'&&S.doc)return loadReader();const f={home,library,courses,chat,knowledge,notes,review,analytics,account,settings};frame((f[S.route]||home)())}catch(e){frame(`<div class="card pad"><h2>加载失败</h2><p class="subtitle">${esc(e.message)}</p></div>`)} }
function row(d){return `<div class="doc-row" onclick="go('reading','${d.id}')" style="cursor:pointer"><div class="doc-icon">${esc(d.type)}</div><div class="doc-info"><strong>${esc(d.title)}</strong><span>${esc(d.course)} · ${d.pages} pages · ${esc(d.lastRead)}</span><div class="progress" style="margin-top:8px"><i style="width:${d.progress*100}%"></i></div></div><div class="meta">${Math.round(d.progress*100)}%</div></div>`}
function stats(){const a=S.analytics||{};return `<div class="grid grid-4" style="margin-top:16px">${[['Documents',a.documents??S.docs.length,'SQLite catalog'],['Questions asked',a.questions||0,`${a.weeklyQuestions||0} in 7 days`],['Concepts',a.concepts||S.knowledge.length,'persistent mastery'],['Notes',a.notes||0,'SQLite notes']].map(x=>`<div class="card stat"><div class="stat-top">${x[0]} <span>↗</span></div><div class="stat-value">${x[1]} <span class="stat-note">${x[2]}</span></div></div>`).join('')}</div>`}
function home(){const d=S.docs[0];const g=homeGreeting();return `<div class="page-title"><div><div class="eyebrow">${homeDateLabel()}</div><h1>${g.title}</h1><div class="subtitle">${g.subtitle}</div></div><button class="btn btn-primary" onclick="go('library')">＋ Add document</button></div><div class="hero"><div class="eyebrow">Your learning loop</div><h2>Read with a little more intention.</h2><p>StudyAgent connects what you read, what you ask, and what you should review next — so every session compounds.</p><button class="btn btn-primary" onclick="go('reading','${d?.id||''}')">Continue reading →</button></div>${stats()}<div class="grid grid-2"><section><div class="section-head"><h2>Continue reading</h2><button class="btn-ghost" onclick="go('library')">View library →</button></div><div class="card pad">${S.docs.slice(0,3).map(row).join('')}</div></section><section><div class="section-head"><h2>Today’s focus</h2><span class="muted">2 of 4 complete</span></div><div class="card pad">${[['Read Chapter 3 · Backward Error','Numerical Analysis · 18 min',0],['Review 3 knowledge cards','Spaced repetition · 8 min',0],['Capture one learning question','Reflection · 3 min',1],['Weekly learning summary','StudyAgent · 5 min',1]].map(x=>`<div class="task"><div class="check ${x[2]?'done':''}">${x[2]?'✓':''}</div><div class="task-text">${x[0]}<small>${x[1]}</small></div></div>`).join('')}</div></section></div><div class="grid grid-2"><section><div class="section-head"><h2>Weak knowledge</h2><button class="btn-ghost" onclick="go('knowledge')">Explore →</button></div><div class="card pad">${S.knowledge.slice(1,4).map(k=>`<div class="weak-item"><div class="ring" style="--p:${k.mastery*100}%"><span>${Math.round(k.mastery*100)}%</span></div><div><strong style="font-size:12px">${esc(k.name)}</strong><div class="meta">${esc(k.description)}</div></div></div>`).join('')}</div></section><section><div class="section-head"><h2>Recent knowledge</h2><button class="btn-ghost" onclick="go('knowledge')">View all →</button></div><div class="card pad">${S.cards.slice(0,3).map(c=>`<div class="doc-row"><div class="doc-icon">CARD</div><div class="doc-info"><strong>${esc(c.front)}</strong><span>${esc(c.source)} · due ${c.due}</span></div></div>`).join('')}</div></section></div>`}
function library(){const ds=S.docs.filter(d=>!S.search||d.title.toLowerCase().includes(S.search.toLowerCase())||d.course.toLowerCase().includes(S.search.toLowerCase()));return `<div class="page-title"><div><div class="eyebrow">Your knowledge base</div><h1>Library</h1><div class="subtitle">${S.docs.length} documents · organized for retrieval</div></div><div><button class="btn btn-secondary" onclick="toast('Collections are ready for your next organizing pass')">＋ Collection</button> <select id="upload-course" class="upload-course" aria-label="上传到课程"><option value="">未分类</option></select> <button class="btn btn-primary" onclick="document.getElementById('file').click()">＋ Upload</button><input id="file" type="file" multiple accept="${learningFileTypes}" style="display:none" onchange="upload(event)" /></div></div>${stats()}<div class="section-head"><h2>All documents</h2><span class="muted">Sort: Recently read · Filter: All types</span></div><div class="library-grid"><div class="card upload" onclick="document.getElementById('file').click()"><div><div style="font-size:27px;color:var(--purple)">↑</div><strong>Drop files to upload</strong><span>PDF, Word, PowerPoint, Markdown, TXT, Excel, CSV, images</span></div></div>${ds.map(d=>`<div class="card doc-card" onclick="go('reading','${d.id}')"><div class="doc-icon">${esc(d.type)}</div><strong>${esc(d.title)}</strong><span class="meta">${esc(d.course)} · ${d.pages} pages · ${esc(d.size)}</span><div class="progress"><i style="width:${d.progress*100}%"></i></div><div style="margin-top:12px">${(d.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></div>`).join('')}</div>`}
function courses(){return `<div class="page-title"><div><div class="eyebrow">Structured learning</div><h1>Courses</h1><div class="subtitle">Keep course context close to the materials you read.</div></div><button class="btn btn-primary" onclick="createLearningCourse()">＋ New course</button></div><div id="learning-courses-grid" class="grid grid-2"><div class="card pad"><p class="subtitle">正在加载真实课程与资料…</p></div></div>`}
function renderPlainAiText(value){return esc(value).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\n/g,'<br/>')}
function renderAiText(text){const source=String(text||'');const formulaPattern=/(\$\$[\s\S]*?\$\$|\\\[[\s\S]*?\\\]|\\\([\s\S]*?\\\)|(?<!\$)\$[^$\n]+\$(?!\$))/g;let html='';let cursor=0;for(const match of source.matchAll(formulaPattern)){const start=match.index??0;html+=renderPlainAiText(source.slice(cursor,start));const token=match[0];const latex=token.startsWith('$$')?token.slice(2,-2):token.startsWith('\\[')?token.slice(2,-2):token.startsWith('\\(')?token.slice(2,-2):token.slice(1,-1);html+=`<div class="ai-formula">${mathmlForLatex(latex.trim())}</div>`;cursor=start+token.length}html+=renderPlainAiText(source.slice(cursor));return html}
function normalizeReviewFormulaText(value,card={}){let source=String(value||'').replace(/FORMULA CANDIDATE\s*·?\s*\d+%?/gi,'').replace(/\s+/g,' ').replace(/(?<=[\u4e00-\u9fff])\s+(?=[\u4e00-\u9fff])/g,'').replace(/邱耆师/g,'邵老师').replace(/Programmer「s/g,"Programmer's").replace(/Chapter 2\s+s\s+What/g,'Chapter 2. What').replace(/O\.H(?:allaron|Hallaron)/g,"O'Hallaron").replace(/0\.1\s*An/g,'0.1 An').replace(/0\.1\.1\s*/g,'0.1.1 ').replace(/吴入误差/g,'舍入误差').replace(/erron/g,'error').replace(/\b4\s+E\s+C“\*“/g,'\\(A \\in \\mathbb{C}^{m\\times n}\\)').replace(/\b4\s+E\s+C(?:mxn|7X“?)/g,'\\(A \\in \\mathbb{C}^{m\\times n}\\)').replace(/\b4\s+E\s+C“““/g,'\\(A \\in \\mathbb{C}^{n\\times n}\\)').replace(/\b4\s+E\s+C[“"^*×xmn+]{0,10}/g,'\\(A \\in \\mathbb{C}^{n}\\)').replace(/\b5\s+E\s+C[“"^*×xmn+]{0,10}/g,'\\(b \\in \\mathbb{C}^{n}\\)').replace(/\bz:\s*E\s+C[“"^*]{0,5}/g,'z \\in \\mathbb{C}^{n}').replace(/\bw\s+E\s+C“/g,'u \\in \\mathbb{C}^{m}').replace(/\bw\s+E\s+CP/g,'v \\in \\mathbb{C}^{n}').replace(/\b4z\s*[二五=]\s*5\b/g,'\\(Az = b\\)').replace(/\b4z\s*五\s*z\b/g,'\\(Az = \\lambda z\\)').replace(/\b4Hw\s*[一-]\s*u\b/g,'\\(A^H u = v\\sigma\\)').replace(/\b4w\s*[一-]\s*u\b/g,'\\(Av = u\\sigma\\)').replace(/\bminzecn\s+4z\s*[一-]\s*[^,。]{0,30}/g,'\\(\\min_{z\\in\\mathbb{C}^{n}} \\|Az-b\\|_2\\)').replace(/Sylvester\s*方程\s*4\s*又\s*一\s*叉\s*习\s*二\s*C/g,'Sylvester 方程 \\(AX-XB=C\\)').replace(/矩阵出数乙\s*4\)/g,'矩阵函数 \\(f(A)\\)');const latex=String(card.locator?.formulaLatex||'').trim();if(latex&&!source.includes(latex)&&!source.includes('\\('))source+=`\\n\\(${latex}\\)`;return source}
function citationMarkup(c,index=1){const locator=c.locator||{};const page=Number(c.page||c.slide||c.sheet||locator.page||locator.slide||locator.sheet||0);const label=c.label||c.citation||c.document||'来源资料';const target=c.documentId&&page>0;return target?`<button type="button" class="citation citation-link" data-document-id="${esc(c.documentId)}" data-page="${page}">[${c.id||index}] ${esc(label)}</button>`:`<span class="citation">[${c.id||index}] ${esc(label)}</span>`}
function message(m){const memory=(m.memoryAssociations||[]).slice(0,2);return `<div class="bubble ${m.role}">${m.role==='assistant'?renderAiText(m.text):esc(m.text)}${m.provider?`<small class="message-model">${esc(m.provider)} · ${esc(m.model||'')}</small>`:''}${memory.length?`<div class="memory-association"><strong>与你之前学习内容的关联</strong>${memory.map(item=>`<span>• ${esc(item.question)}</span>`).join('')}</div>`:''}${(m.citations||[]).map((c,index)=>citationMarkup(c,index+1)).join('')}</div>`}
function isMathOcrModel(config){return config?.provider==='mathpix'||config?.apiType==='mathpix'||config?.purpose==='math-ocr'}
function modelPicker(){const active=currentModelConfig();return `<div class="ai-model-bar"><span>AI Model</span><select onchange="S.activeModelId=this.value;toast('后续问题将使用所选模型')"><option value="local" ${S.activeModelId==='local'?'selected':''}>Local Study Agent</option>${S.modelConfigs.filter(config=>!isMathOcrModel(config)).map(config=>`<option value="${esc(config.id)}" ${config.id===(S.activeModelId||active.id)?'selected':''}>${esc(config.providerName||config.provider)} · ${esc(config.model)}</option>`).join('')}</select><button class="tiny-btn" onclick="go('settings')">设置</button></div>`}
function chat(){return `<div class="page-title"><div><div class="eyebrow">Evidence-first tutor</div><h1>AI Chat</h1><div class="subtitle">Ask across your selected learning scope. Every answer carries its evidence.</div></div><span class="mode-pill"><i class="dot"></i> Local retrieval active</span></div><div class="card pad" style="max-width:780px"><div class="scope">Scope: Entire library · Retrieval top-8 · Retrieved chunks only</div><div class="messages" style="max-height:500px">${S.messages.map(message).join('')}</div><div class="chat-composer"><textarea id="chat-input" placeholder="Ask about Forward Error, Backward Error, or your library…"></textarea><button class="send" onclick="send('chat-input')">↑</button></div></div>`}
function knowledge(){return `<div class="page-title"><div><div class="eyebrow">What you know, and what needs attention</div><h1>Knowledge</h1><div class="subtitle">${S.knowledge.length} concepts · ${S.cards.length} cards · mastery updates after review</div></div><button class="btn btn-primary" onclick="card()">＋ Create card</button></div><div class="knowledge-layout"><div class="card pad"><div class="section-head" style="margin-top:0"><h2>Knowledge points</h2><span class="muted">Sorted by weak mastery</span></div>${[...S.knowledge].sort((a,b)=>a.mastery-b.mastery).map(k=>`<div class="kp-row"><div class="doc-icon" style="background:${k.color}22;color:${k.color}">◇</div><div class="kp-main"><strong>${esc(k.name)}</strong><span>${esc(k.description)} · ${esc(k.source)}</span></div><div class="mastery"><b>${Math.round(k.mastery*100)}%</b><div class="progress"><i style="width:${k.mastery*100}%;background:${k.color}"></i></div></div></div>`).join('')}</div><div class="card pad"><div class="section-head" style="margin-top:0"><h2>Knowledge graph</h2><span class="muted">真实概念关系</span></div><div id="knowledge-graph-live" class="graph"><div class="graph-loading">正在加载真实概念图谱…</div></div><div id="concept-detail" class="concept-detail"><span class="meta">点击概念节点查看来源、历史问题和关联概念。</span></div><div id="graph-management" class="graph-management"><span class="meta">正在加载关系管理…</span></div></div></div><div class="section-head"><h2>Flashcards</h2><button class="btn-ghost" onclick="go('review')">Review due cards →</button></div><div class="grid grid-2">${S.cards.map(c=>`<div class="card pad"><div class="eyebrow">${esc(c.source)} · ${esc(c.due)}</div><h3>${esc(c.front)}</h3><p class="subtitle" style="line-height:1.7;margin-bottom:0">${esc(c.back)}</p></div>`).join('')}</div>`}
function notes(){return `<div class="page-title"><div><div class="eyebrow">Your thinking layer</div><h1>Notes</h1><div class="subtitle">Markdown-friendly notes, connected to source pages and knowledge points.</div></div><button class="btn btn-primary" onclick="note()">＋ New note</button></div><div id="notes-list" class="notes-list"><div class="card pad"><p class="subtitle">正在加载本地持久化笔记…</p></div></div>`}
function review(){const c=S.cards[0]||{};return `<div class="page-title"><div><div class="eyebrow">Spaced repetition · SM-2 inspired</div><h1>Review</h1><div class="subtitle">${S.reviews.length} tasks due today · short sessions compound over time.</div></div><span class="mode-pill"><i class="dot"></i> 8 min planned</span></div><div class="review-grid"><div class="card review-card" id="review-card"><div class="eyebrow">Knowledge card · ${esc(c.source||'')}</div><div class="question">${esc(c.front||'No cards yet')}</div><div class="answer">${renderAiText(normalizeReviewFormulaText(c.back||'',c))}</div><button class="btn btn-primary" onclick="reveal()">Show answer</button><div style="display:flex;justify-content:center;gap:8px;margin-top:14px"><button class="btn btn-secondary" onclick="complete()">Again</button><button class="btn btn-secondary" onclick="complete()">Got it ✓</button></div></div><div class="card pad"><div class="section-head" style="margin-top:0"><h2>Today’s queue</h2><span class="muted">${S.reviews.length} due</span></div>${S.reviews.map(t=>`<div class="task"><div class="check" style="border-color:#f2c6a3;background:#fff4e8">•</div><div class="task-text"><strong>${esc(t.title)}</strong><small>${esc(t.reason)}</small></div></div>`).join('')||'<p class="subtitle">All caught up. Nice work.</p>'}<div class="section-head"><h2>Review habit</h2></div><div class="progress"><i style="width:72%;background:var(--green)"></i></div><div class="meta" style="margin-top:8px">6 day streak · 72% weekly consistency</div></div><section class="card pad review-self-test" id="review-self-test"><div class="section-head" style="margin-top:0"><div><h2>综合自测</h2><span class="muted">概念解释、公式识别、比较辨析、应用推理、错误诊断和证据概括</span></div><button class="btn btn-primary" onclick="generateReviewQuiz()">生成 6 道多样题</button></div><div class="agent-output"><p class="subtitle">题目会从当前学习资料库检索生成，并保留页码或区段来源。</p></div></section></div>`}
function analytics(){const a=S.analytics||{dailyActivity:[],mastery:[]};const activity=a.dailyActivity||[];const maxActivity=Math.max(1,...activity.map(item=>Number(item.questions||0)+Number(item.annotations||0)+Number(item.notes||0)));return `<div class="page-title"><div><div class="eyebrow">Make learning visible</div><h1>Learning Analytics</h1><div class="subtitle">A lightweight view of your actual local learning events.</div></div><span class="meta">Last 7 days · SQLite</span></div>${[['Weekly questions',a.weeklyQuestions||0],['Documents with questions',a.pages||0],['All questions',a.questions||0],['Annotations',a.annotations||0],['Notes',a.notes||0]].map(x=>`<div class="card stat" style="display:inline-block;width:19%;margin-right:1%"><div class="stat-top">${x[0]}</div><div class="stat-value">${x[1]}</div></div>`).join('')}<div class="grid grid-2" style="margin-top:16px"><div class="card pad"><div class="section-head" style="margin-top:0"><h2>Daily learning activity</h2><span class="muted">questions · notes · annotations</span></div><div class="analytics-bars">${activity.map(item=>{const total=Number(item.questions||0)+Number(item.annotations||0)+Number(item.notes||0);return `<div class="bar-wrap"><div class="bar" style="height:${Math.max(4,total/maxActivity*100)}%" title="${total} events"></div><div class="bar-label">${esc(item.date?.slice(5)||'')}</div></div>`}).join('')}</div></div><div class="card pad"><div class="section-head" style="margin-top:0"><h2>Mastery snapshot</h2><span class="muted">current</span></div>${(a.mastery||[]).map(m=>`<div class="kp-row"><div class="kp-main"><strong>${esc(m.name)}</strong></div><div class="mastery"><b>${m.value}%</b><div class="progress"><i style="width:${m.value}%"></i></div></div></div>`).join('')||'<p class="subtitle">还没有持久化学习概念。</p>'}</div></div>`}
function currentModelConfig(){if(S.activeModelId==='local')return {id:'local',provider:'local',model:'Evidence-first local mode',streaming:false};const chatConfigs=S.modelConfigs.filter(config=>!isMathOcrModel(config));return chatConfigs.find(config=>config.id===S.activeModelId)||chatConfigs.find(config=>config.isDefault)||chatConfigs[0]||{} }
function settings(){const config=currentModelConfig();const provider=S.modelProviders.find(item=>item.id===(config.provider||'custom'))||S.modelProviders.find(item=>item.id==='custom')||{};const models=S.availableModels.length?S.availableModels:(provider.models||[]);return `<div class="page-title"><div><div class="eyebrow">Secure provider registry · local encrypted config</div><h1>AI Model Settings</h1><div class="subtitle">接入真实模型，API Key 只在本地服务端使用，页面只显示掩码。</div></div><span class="mode-pill"><i class="dot"></i> ${config.id?'Configured':'Local mode'}</span></div><div class="card pad settings"><div class="section-head" style="margin-top:0"><h2>Provider & Model</h2><span class="muted">模型定义集中在 Model Registry</span></div><div class="setting-row"><div><label>Provider<small>选择后自动填写 Base URL，可继续手动修改。</small></label></div><select id="modelProvider" onchange="modelProviderChanged()">${S.modelProviders.map(item=>`<option value="${esc(item.id)}" ${item.id===provider.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select></div><div class="setting-row"><div><label>Model<small>动态列表失败时使用 Registry fallback。</small></label></div><select id="modelName">${models.map(item=>`<option value="${esc(item.id)}" ${item.id===(config.model||models[0]?.id)?'selected':''}>${esc(item.label||item.id)}</option>`).join('')}</select></div><div class="setting-row"><div><label>API Key<small>${config.hasApiKey?'已保存 '+esc(config.apiKey):'未配置；不会写入 studyagent.json'}</small></label></div><div class="inline-control"><input id="modelApiKey" type="password" placeholder="输入新的 API Key" autocomplete="off" /><button class="tiny-btn" onclick="toggleApiKey()">显示</button></div></div><div class="setting-row"><div><label>Base URL / API URL<small>支持 OpenAI-compatible 自定义地址。</small></label></div><input id="modelBaseUrl" value="${esc(config.baseUrl||provider.baseUrl||'')}" /></div><div class="setting-row"><div><label>Organization ID<small>仅部分服务商需要。</small></label></div><input id="modelOrganization" value="${esc(config.organizationId||'')}" /></div><div class="setting-row"><div><label>Temperature</label></div><input id="modelTemperature" type="number" step="0.1" min="0" max="2" value="${Number(config.temperature??0.2)}" /></div><div class="setting-row"><div><label>Max Tokens</label></div><input id="modelMaxTokens" type="number" min="1" max="200000" value="${Number(config.maxTokens||1200)}" /></div><div class="setting-row"><div><label>Timeout (ms)</label></div><input id="modelTimeout" type="number" min="1000" value="${Number(config.timeout||45000)}" /></div><div class="setting-row"><div><label>Streaming<small>OpenAI-compatible接口支持实时输出。</small></label></div><label class="check-row"><input id="modelStreaming" type="checkbox" ${config.streaming!==false?'checked':''}/> Enabled</label></div><div class="setting-row"><div><label>Custom Headers<small>JSON object，可留空。</small></label></div><textarea id="modelHeaders" placeholder='{"X-Custom-Header":"value"}'>${esc(JSON.stringify(config.headers||{},null,2))}</textarea></div><div class="setting-row"><div><label>Default model<small>后续 AI 阅读问题默认使用此配置。</small></label></div><label class="check-row"><input id="modelDefault" type="checkbox" ${config.isDefault?'checked':''}/> Use as default</label></div><div class="model-actions"><button class="btn btn-secondary" onclick="refreshModels()">刷新模型列表</button><button class="btn btn-secondary" onclick="testSelectedModel()">测试连接</button><button class="btn btn-primary" onclick="saveModelConfig()">保存配置</button>${config.id?'<button class="btn btn-danger" onclick="deleteModelConfig()">删除配置</button>':''}</div><div id="modelStatus" class="model-status">${config.hasApiKey?'已加载本地加密配置。':'未配置远程模型时使用 Local Study Agent。'}</div></div><div class="card pad settings" style="margin-top:16px"><div class="section-head" style="margin-top:0"><h2>Privacy boundary</h2></div><div class="setting-row"><div><label>Context sent to provider<small>默认只发送当前选择和附近文本，不发送整篇 PDF。</small></label></div><select id="privacy"><option value="selected-only" ${S.settings.privacy==='selected-only'?'selected':''}>Selected text only</option><option value="current-page" ${S.settings.privacy==='current-page'?'selected':''}>Current page</option><option value="retrieved-chunks" ${!S.settings.privacy||S.settings.privacy==='retrieved-chunks'?'selected':''}>Retrieved chunks</option></select></div><div class="setting-row"><div><label>Retrieval top-K</label></div><input id="retrievalK" type="number" value="${Number(S.settings.retrievalK||8)}" min="1" max="20" /></div><div style="display:flex;justify-content:flex-end;margin-top:18px"><button class="btn btn-primary" onclick="saveSettings()">Save privacy settings</button></div></div>`}
function selectedProviderRecord(){return S.modelProviders.find(item=>item.id===document.getElementById('modelProvider')?.value)||{} }
function modelProviderChanged(){const provider=selectedProviderRecord();const base=document.getElementById('modelBaseUrl');if(base)base.value=provider.baseUrl||'';const select=document.getElementById('modelName');if(select)select.innerHTML=(provider.models||[]).map(item=>`<option value="${esc(item.id)}">${esc(item.label||item.id)}</option>`).join('');S.availableModels=provider.models||[];}
function toggleApiKey(){const input=document.getElementById('modelApiKey');const button=input?.nextElementSibling;if(!input)return;input.type=input.type==='password'?'text':'password';if(button)button.textContent=input.type==='password'?'显示':'隐藏'}
function modelForm(){let headers={};try{headers=JSON.parse(document.getElementById('modelHeaders')?.value||'{}')}catch{throw Error('Custom Headers 必须是合法 JSON')};return {id:S.activeModelId||undefined,provider:document.getElementById('modelProvider')?.value,model:document.getElementById('modelName')?.value,apiKey:document.getElementById('modelApiKey')?.value,baseUrl:document.getElementById('modelBaseUrl')?.value,organizationId:document.getElementById('modelOrganization')?.value,temperature:Number(document.getElementById('modelTemperature')?.value||0.2),maxTokens:Number(document.getElementById('modelMaxTokens')?.value||1200),timeout:Number(document.getElementById('modelTimeout')?.value||45000),streaming:Boolean(document.getElementById('modelStreaming')?.checked),isDefault:Boolean(document.getElementById('modelDefault')?.checked),headers}}
async function saveModelConfig(){try{const saved=await api('/api/models/configs',{method:'POST',body:JSON.stringify(modelForm())});S.activeModelId=saved.id;const data=await api('/api/models/configs');S.modelConfigs=data.configs||[];S.activeModelId=data.defaultId||saved.id;toast('模型配置已加密保存');render()}catch(error){toast(error.message)}}
async function refreshModels(){try{const form=modelForm();const current=currentModelConfig();if(!form.apiKey&&!current.hasApiKey)return toast('请先在当前配置中输入 API Key 后刷新');const result=await api('/api/models/discover',{method:'POST',body:JSON.stringify(form)});S.availableModels=result.models||[];toast(result.source==='remote'?`已刷新 ${S.availableModels.length} 个远程模型`:'远程列表不可用，已使用本地 fallback');render()}catch(error){toast(error.message)}}
async function testSelectedModel(){try{if(!S.activeModelId){await saveModelConfig();return}const result=await api(`/api/models/configs/${S.activeModelId}/test`,{method:'POST'});const status=document.getElementById('modelStatus');if(status)status.textContent=result.ok?`✓ API Connected · ${result.latencyMs} ms · ${result.model}`:`${result.error?.code||'Failed'} ${result.error?.message||''}`;toast(result.ok?'连接成功':(result.error?.message||'连接失败'))}catch(error){toast(error.message)}}
async function deleteModelConfig(){if(!S.activeModelId)return;try{await api(`/api/models/configs/${S.activeModelId}`,{method:'DELETE'});S.activeModelId='';S.modelConfigs=(await api('/api/models/configs')).configs||[];toast('模型配置已删除');render()}catch(error){toast(error.message)}}
function mathOcrConfig(){return S.modelConfigs.find(config=>config.apiType==='mathpix'||config.provider==='mathpix'||config.purpose==='math-ocr')||{}}
function mathOcrPanel(){if(S.route!=='settings'||document.getElementById('math-ocr-settings'))return;const config=mathOcrConfig();const anchor=document.querySelector('.settings');if(!anchor)return;anchor.insertAdjacentHTML('afterend',`<div id="math-ocr-settings" class="card pad settings" style="margin-top:16px"><div class="section-head" style="margin-top:0"><div><h2>专用数学 OCR</h2><span class="muted">使用 Mathpix 识别扫描讲义中的公式，并保存 LaTeX 到当前资料页。密钥只保存在本地服务端。</span></div><span class="tag">${config.hasApiKey?'已配置':'未配置'}</span></div><div class="setting-row"><div><label>Mathpix App ID<small>从 Mathpix 控制台获取，不是通用模型 API Key。</small></label></div><input id="mathOcrAppId" value="${esc(config.appId||config.organizationId||'')}" autocomplete="off" /></div><div class="setting-row"><div><label>Mathpix App Key<small>${config.hasApiKey?'已保存 '+esc(config.apiKey):'未配置；不会写入前端源码。'}</small></label></div><input id="mathOcrApiKey" type="password" placeholder="输入 App Key" autocomplete="off" /></div><div class="setting-row"><div><label>Mathpix Base URL</label></div><input id="mathOcrBaseUrl" value="${esc(config.baseUrl||'https://api.mathpix.com/v3')}" /></div><div class="model-actions"><button class="btn btn-primary" onclick="saveMathOcrConfig()">保存数学 OCR 配置</button>${config.id?`<button class="btn btn-danger" onclick="deleteMathOcrConfig()">删除数学 OCR 配置</button>`:''}</div><div id="math-ocr-status" class="model-status">${config.hasApiKey?'可在阅读器解析视图中识别当前页公式。':'配置后可在阅读器中调用专用数学 OCR。'}</div></div>`)}
async function saveMathOcrConfig(){try{const existing=mathOcrConfig();const saved=await api('/api/models/configs',{method:'POST',body:JSON.stringify({id:existing.id,provider:'mathpix',providerName:'Mathpix Math OCR',apiType:'mathpix',model:'mathpix-text',purpose:'math-ocr',appId:document.getElementById('mathOcrAppId')?.value.trim(),apiKey:document.getElementById('mathOcrApiKey')?.value,baseUrl:document.getElementById('mathOcrBaseUrl')?.value.trim()||'https://api.mathpix.com/v3',isDefault:false})});const data=await api('/api/models/configs');S.modelConfigs=data.configs||[];toast('专用数学 OCR 配置已加密保存');mathOcrPanel();document.getElementById('math-ocr-status')?.replaceChildren(document.createTextNode(saved.hasApiKey?'配置成功，可在阅读器中识别公式。':'配置已保存，但还没有 App Key。'))}catch(error){toast(error.message)}}
async function deleteMathOcrConfig(){const config=mathOcrConfig();if(!config.id)return;try{await api(`/api/models/configs/${encodeURIComponent(config.id)}`,{method:'DELETE'});S.modelConfigs=(await api('/api/models/configs')).configs||[];toast('专用数学 OCR 配置已删除');document.getElementById('math-ocr-settings')?.remove();mathOcrPanel()}catch(error){toast(error.message)}}
window.saveMathOcrConfig=saveMathOcrConfig;window.deleteMathOcrConfig=deleteMathOcrConfig;
function fileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const bytes=new Uint8Array(reader.result),chunk=0x8000;let binary='';for(let i=0;i<bytes.length;i+=chunk)binary+=String.fromCharCode(...bytes.subarray(i,i+chunk));resolve(btoa(binary))};reader.onerror=reject;reader.readAsArrayBuffer(file)})}
async function upload(e){const files=Array.from(e.target.files||[]);if(!files.length)return;const textTypes=/\.(md|markdown|txt|csv)$/i;try{toast(files.length>1?`正在导入 ${files.length} 个文件…`:files[0].name.toLowerCase().endsWith('.pdf')?'正在读取 PDF 并检测扫描页…':'正在读取文件…');const payloads=await Promise.all(files.map(async file=>textTypes.test(file.name)?{name:file.name,size:file.size,content:await file.text()}:{name:file.name,size:file.size,base64:await fileBase64(file)}));const courseId=document.getElementById('upload-course')?.value||undefined;const result=payloads.length>1?await api('/api/documents/upload-batch',{method:'POST',body:JSON.stringify({files:payloads,courseId})}):await api('/api/documents/upload',{method:'POST',body:JSON.stringify({...payloads[0],courseId})});const imported=result.documents||[result];S.docs.unshift(...imported);if(result.errors?.length)toast(`已导入 ${imported.length} 个，${result.errors.length} 个失败`);else toast(imported.length>1?`已导入 ${imported.length} 个文件`:'已加入 Library');await render()}catch(error){toast(error.message)}finally{e.target.value=''}}
async function openCitation(documentId,page=1){if(!documentId)return;let doc=S.docs.find(item=>item.id===documentId);try{if(!doc)doc=await api(`/api/documents/${encodeURIComponent(documentId)}`)}catch(error){return toast(`无法打开引用资料：${error.message}`)}if(!doc)return toast('引用资料不存在');if(S.doc?.id!==doc.id)S.conversationId='';S.doc=doc;S.p=Math.max(1,Number(page)||1);S.route='reading';await loadReader()}
async function ensureLearningSession(){if(!S.doc?.id||S.learningSessionDocumentId===S.doc.id&&S.learningSessionId)return;const session=await api('/api/learning/sessions',{method:'POST',body:JSON.stringify({documentId:S.doc.id,courseId:S.doc.courseId||null,workspaceId:S.doc.workspaceId||undefined})});S.learningSessionId=session.id;S.learningSessionDocumentId=S.doc.id}
async function finishLearningSession(){if(!S.learningSessionId)return toast('当前没有活动学习会话');try{const result=await api(`/api/learning/sessions/${encodeURIComponent(S.learningSessionId)}/finish`,{method:'POST',body:'{}'});toast(`学习经历已保存：${result.experience?.title||'本次学习'}`);S.learningSessionId='';S.learningSessionDocumentId=''}catch(error){toast(error.message)}}
async function loadReader(){if(!S.doc)S.doc=S.docs[0];if(!S.doc)return;S.pages=await api(`/api/documents/${S.doc.id}/pages`);if(S.p>S.pages.length)S.p=1;await ensureLearningSession();if(!S.conversationId)S.conversationId=`conversation-document-${S.doc.id}`;try{const history=await api(`/api/conversations/${encodeURIComponent(S.conversationId)}/messages?limit=100`);if(Array.isArray(history.messages)){S.messages=history.messages.map(item=>{const metadata=item.metadata||{};return{role:item.role,text:item.content||'',selectedText:metadata.selectedText||'',formula:metadata.formula||'',citations:Array.isArray(metadata.citations)?metadata.citations:[],provider:metadata.provider,model:metadata.model,mode:metadata.mode}})}}catch(error){console.warn('conversation history unavailable',error)}reader()}
function reader(){const d=S.doc,p=S.pages[S.p-1]||S.pages[0];let side=`<div class="scope">Scope: Current page · ${esc(p.heading)}</div><div class="messages">${S.messages.slice(-5).map(message).join('')}</div><div class="chat-composer"><textarea id="reader-input" placeholder="Ask this page…"></textarea><button class="send" onclick="send('reader-input')">↑</button></div>`;if(S.tab==='Summary')side=`<div class="bubble assistant">${esc(p.text)}${citationMarkup({id:1,documentId:d.id,page:p.page,label:`${d.title} · Page ${p.page}`})}</div><button class="btn btn-secondary" onclick="summarize()">Generate a richer summary</button>`;if(S.tab==='Notes')side=`<div class="bubble assistant">Your notes for this page</div><button class="btn btn-primary" onclick="note()">＋ Add note</button>`;frame(`<div class="reader-head"><button class="btn btn-secondary" onclick="go('library')">← Library</button><div class="doc-icon">${esc(d.type)}</div><div><h3>${esc(d.title)}</h3><div class="meta">${esc(d.course)} · ${d.pages} pages · progress ${Math.round(d.progress*100)}%</div></div></div><div class="reader-layout"><aside class="outline"><h3>Document outline</h3>${S.pages.map(x=>`<div class="outline-item ${x.page===p.page?'active':''}" onclick="S.p=${x.page};reader()">${x.page}. ${esc(x.heading)}</div>`).join('')}</aside><section class="viewer-wrap"><div class="viewer-toolbar"><div class="toolbar-group"><button class="tiny-btn" onclick="S.p=Math.max(1,S.p-1);reader()">← Prev</button><button class="tiny-btn" onclick="S.p=Math.min(S.pages.length,S.p+1);reader()">Next →</button><button class="tiny-btn" onclick="setReaderZoom(Math.max(80,S.zoom-10))">−</button><button class="tiny-btn" onclick="setReaderZoom(Math.min(130,S.zoom+10))">＋</button></div><span class="page-chip">Page ${p.page} of ${S.pages.length}</span><div class="toolbar-group"><button class="tiny-btn" onclick="summarize()">Summarize</button><button class="tiny-btn" onclick="note()">＋ Note</button></div></div><div class="paper" onmouseup="selectText(event)"><div class="paper-label">${esc(d.course)} · reading note</div><h2>${esc(p.heading)}</h2><p>${esc(p.text)}</p>${p.page===3?'<div class="formula">computed result = exact solution of a nearby problem</div>':''}<p style="color:#8b8d99;font-size:11px">Select a sentence to highlight it, ask a question, or create a card. Your annotation is saved locally.</p></div><div id="tools" class="float-tools"><button onclick="highlight()">Highlight</button><button onclick="askSelected('explain')">Explain</button><button onclick="askSelected('derive')">Detailed derivation</button><button onclick="askSelected('why')">Why</button><button onclick="askSelected('relate')">Connect history</button><button onclick="askSelected('quiz')">Generate quiz</button><button onclick="card()">Create card</button><button onclick="note()">Note</button></div></section><aside class="ai-panel"><div class="section-head" style="margin:0 0 5px"><h3>AI learning panel</h3><span class="mode-pill" style="margin:0;padding:5px 7px;font-size:9px"><i class="dot"></i> Local</span></div><div class="ai-tabs">${['Chat','Summary','Notes'].map(t=>`<button class="${S.tab===t?'active':''}" onclick="S.tab='${t}';reader()">${t}</button>`).join('')}</div>${side}</aside></div>`)}
const renderMathmlBase=mathmlForLatex;
mathmlForLatex=function(latex){return renderMathmlBase(String(latex||'').replace(/\\min\b/g,'min').replace(/\\max\b/g,'max').replace(/\\\|/g,'‖'))};
const normalizeReviewFormulaBase=normalizeReviewFormulaText;
normalizeReviewFormulaText=function(value,card){return normalizeReviewFormulaBase(String(value||'').replace(/\b4\s+E\s+C7X“?/g,'4 E C“““').replace(/\b4\s+E\s+C“xn/g,'4 E C“*“').replace(/\b4\s+E\s+Cmx/g,'4 E C“*“').replace(/\bminzecn\b[^,。]{0,60}/g,'minzecn 4z 一'),card||{}).replace(/》\s*E\s+C[“"^*]{0,5}/g,'\\(b \\in \\mathbb{C}^{m}\\)').replace(/\\\(\\min/g,'\\(min')};
function selectText(e){const x=window.getSelection()?.toString().trim();if(!x)return;S.selection=x;S.selectionLatex='';const t=document.getElementById('tools');t.style.left=Math.min(e.offsetX,document.querySelector('.viewer-wrap').clientWidth-330)+'px';t.style.top=Math.max(50,e.offsetY-40)+'px';t.classList.add('show')}
async function highlight(){if(!S.selection)return toast('先在文档中选择一段文字');await api(`/api/documents/${S.doc.id}/annotations`,{method:'POST',body:JSON.stringify({page:S.p,type:'highlight',color:'yellow',text:S.selection,note:S.selectionLatex?`LaTeX: ${S.selectionLatex}`:'',sessionId:S.learningSessionId})});S.ann=await api('/api/annotations');toast('高亮已保存到本地');document.getElementById('tools')?.classList.remove('show')}
async function explain(){if(!S.selection)return toast('先在文档中选择一段文字');const r=await api('/api/ai/explain',{method:'POST',body:JSON.stringify({documentId:S.doc.id,page:S.p,selectedText:S.selection,language:S.settings.language==='en'?'en':'zh'})});S.messages.push({role:'user',text:'Explain: '+S.selection,citations:[]},{role:'assistant',text:r.answer,citations:r.citations||[]});S.tab='Chat';reader()}
async function askSelected(action='explain'){if(!S.selection)return toast('先在文档中选择一段文字');const english=S.settings.language==='en';const prompts={explain:english?'Explain the selected passage clearly.':'请清晰解释选中的内容。',derive:english?'Give a detailed derivation of the selected passage, keeping every important mathematical step.':'请对选中的内容进行详细推导，保留关键数学步骤。',why:english?'Why is the selected statement or method needed?':'为什么需要选中的结论或方法？',relate:english?'Connect the selected passage to my previous learning and explain only meaningful links.':'请将选中的内容与我之前的学习建立有意义的关联，只在确实相关时说明。',quiz:english?'Create one practice question from the selected passage, then give a concise answer and citation.':'请根据选中的内容生成一道练习题，并给出简洁答案和来源引用。'};const question=prompts[action]||prompts.explain;try{const r=await api('/api/chat',{method:'POST',body:JSON.stringify({message:question,documentId:S.doc.id,page:S.p,selectedText:S.selection,scope:'current-page',language:english?'en':'zh',remember:action!=='quiz'})});S.messages.push({role:'user',text:question+'\n'+S.selection,citations:[]},{role:'assistant',text:r.answer,citations:r.citations||[],memoryAssociations:r.memoryAssociations||[],provider:r.provider,model:r.model});S.tab='Chat';document.getElementById('tools')?.classList.remove('show');reader()}catch(error){toast(error.message)}}
async function summarize(){const r=await api('/api/ai/summarize',{method:'POST',body:JSON.stringify({documentId:S.doc.id,page:S.p,language:S.settings.language==='en'?'en':'zh'})});S.messages.push({role:'assistant',text:r.answer,citations:r.citations||[]});S.tab='Chat';reader();toast('页面摘要已生成')}
async function card(){const r=await api('/api/ai/create-card',{method:'POST',body:JSON.stringify({documentId:S.doc?.id||S.docs[0]?.id,page:S.p,selectedText:S.selection,formula:S.selectionLatex||'',language:S.settings.language==='en'?'en':'zh'})});S.cards.unshift(r);toast('知识卡已保存');if(S.route==='knowledge')render();document.getElementById('tools')?.classList.remove('show')}
async function send(id){const i=document.getElementById(id),text=i.value.trim();if(!text)return;S.messages.push({role:'user',text,citations:[]});i.value='';if(S.route==='reading')reader();else render();const r=await api('/api/chat',{method:'POST',body:JSON.stringify({message:text,documentId:S.doc?.id,selectedText:S.selection})});S.messages.push({role:'assistant',text:r.answer,citations:r.citations||[]});if(S.route==='reading')reader();else render()}
function note(){const e=document.createElement('div');e.className='modal-backdrop';e.innerHTML=`<div class="modal"><h2>Add a note</h2><p class="subtitle">${S.selection?'Linked to selected text: '+esc(S.selection.slice(0,90)):'A durable note stays useful after this reading session.'}</p><input id="note-title" placeholder="Note title" /><textarea id="note-text" placeholder="Write your thought, question, or memory tip…"></textarea><div class="modal-actions"><button class="btn btn-secondary" onclick="this.closest('.modal-backdrop').remove()">Cancel</button><button class="btn btn-primary" onclick="saveNote(this)">Save note</button></div></div>`;document.body.append(e);document.getElementById('note-title')?.focus()}
async function saveNote(b){const text=document.getElementById('note-text')?.value.trim();if(!text)return toast('请输入笔记内容');const page=S.pages[S.p-1]||{};try{await api('/api/notes',{method:'POST',body:JSON.stringify({title:document.getElementById('note-title')?.value.trim()||'',content:text,documentId:S.doc?.id||null,courseId:S.doc?.courseId||null,locator:{page:Number(S.p)||undefined,section:page.heading||'',selectedText:S.selection||'',formulaLatex:S.selectionLatex||''}})});b.closest('.modal-backdrop').remove();toast('笔记已保存到本地 SQLite');if(S.route==='notes')loadNotesPage()}catch(error){toast(error.message)}}
function reveal(){document.getElementById('review-card').classList.add('revealed');document.querySelector('#review-card .btn-primary').textContent='Answer revealed'}
async function complete(){const t=S.reviews[0];if(!t)return;await api('/api/review/complete',{method:'POST',body:JSON.stringify({id:t.id})});S.reviews=await api('/api/review/today');toast('Review recorded · mastery updated');render()}
async function saveSettings(){S.settings=await api('/api/settings',{method:'POST',body:JSON.stringify({language:document.getElementById('language')?.value==='en'?'en':'zh',privacy:document.getElementById('privacy').value,retrievalK:Number(document.getElementById('retrievalK').value)})});toast('Language and privacy settings saved locally');await render()}
function closeCommand(){document.querySelector('.command-backdrop')?.remove()}
function command(){closeCommand();const e=document.createElement('div');e.className='modal-backdrop command-backdrop';e.setAttribute('role','presentation');e.innerHTML=`<div class="modal command-modal" role="dialog" aria-modal="true" aria-labelledby="command-title"><div class="modal-title"><h2 id="command-title">Command palette</h2><button class="modal-close" type="button" aria-label="Close command palette" onclick="closeCommand()">×</button></div><input id="cmd" autofocus placeholder="Try: ask AI, create note, library…" style="width:100%;padding:11px;border:1px solid var(--line);border-radius:9px;outline:0" onkeydown="if(event.key==='Escape'){closeCommand()}else if(event.key==='Enter'){const v=this.value.toLowerCase();closeCommand();if(v.includes('note'))note();else if(v.includes('library'))go('library');else go('chat')}}"><div class="meta" style="margin-top:13px">⌘ K · Ask AI · Create Note · Search Library · Esc to close</div></div>`;e.addEventListener('click',event=>{if(event.target===e)closeCommand()});document.body.append(e);document.getElementById('cmd').focus()}
function mathmlForLatex(latex){const source=String(latex||'').replace(/\\left|\\right/g,'').trim();const ops={in:'∈',le:'≤',ge:'≥',times:'×',div:'÷',cdot:'·',alpha:'α',beta:'β',gamma:'γ',lambda:'λ',mu:'μ',omega:'ω',sigma:'σ',pi:'π',infty:'∞',sum:'∑',int:'∫'};const readGroup=(text,start)=>{if(text[start]!=='{')return {value:text[start]||'',next:start+1};let depth=0;for(let i=start;i<text.length;i+=1){if(text[i]==='{')depth+=1;if(text[i]==='}')depth-=1;if(depth===0)return {value:text.slice(start+1,i),next:i+1}}return {value:text.slice(start+1),next:text.length}};const sequence=text=>{const out=[];let i=0;const pushScript=(kind)=>{if(!out.length)return false;const group=text[i+1]==='{'?readGroup(text,i+1):{value:text[i+1]||'',next:i+2};const previous=out.pop();out.push(kind==='^'?`<msup><mrow>${previous}</mrow><mrow>${sequence(group.value)}</mrow></msup>`:`<msub><mrow>${previous}</mrow><mrow>${sequence(group.value)}</mrow></msub>`);i=group.next;return true};while(i<text.length){const ch=text[i];if(ch==='^'||ch==='_'){if(pushScript(ch))continue;i+=1;continue}if(ch==='\\'){const match=text.slice(i+1).match(/^[A-Za-z]+/);const command=match?.[0]||text[i+1]||'';i+=1+command.length;if(command==='frac'){const numerator=readGroup(text,i);const denominator=readGroup(text,numerator.next);out.push(`<mfrac><mrow>${sequence(numerator.value)}</mrow><mrow>${sequence(denominator.value)}</mrow></mfrac>`);i=denominator.next;continue}if(command==='sqrt'){const group=readGroup(text,i);out.push(`<msqrt>${sequence(group.value)}</msqrt>`);i=group.next;continue}if(command==='mathbb'||command==='mathbf'||command==='mathrm'||command==='text'){const group=readGroup(text,i);const variant=command==='mathbb'?'double-struck':command==='mathbf'?'bold':command==='mathrm'?'normal':null;out.push(variant?`<mi mathvariant="${variant}">${esc(group.value)}</mi>`:`<mtext>${esc(group.value)}</mtext>`);i=group.next;continue}if(ops[command]){out.push(`<mo>${ops[command]}</mo>`);continue}out.push(`<mtext>\\${esc(command)}</mtext>`);continue}if(/\s/.test(ch)){i+=1;continue}if(/[A-Za-z]/.test(ch)){out.push(`<mi>${esc(ch)}</mi>`);i+=1;continue}if(/[0-9]/.test(ch)){let end=i+1;while(end<text.length&&/[0-9.]/.test(text[end]))end+=1;out.push(`<mn>${esc(text.slice(i,end))}</mn>`);i=end;continue}if('+-=(),[]<>|'.includes(ch)){out.push(`<mo>${esc(ch)}</mo>`);i+=1;continue}out.push(`<mo>${esc(ch)}</mo>`);i+=1}return out.join('')};return `<math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow>${sequence(source)}</mrow></math>`}
function renderPageContent(page){const formulaBlocks=Array.isArray(page?.formulas)?page.formulas:[];const blocks=Array.isArray(page?.blocks)&&page.blocks.length?page.blocks:formulaBlocks.length?[{type:'paragraph',text:page?.text||''},...formulaBlocks]:[{type:'paragraph',text:page?.text||''}];return blocks.map(block=>{if(block.type==='formula'){const latex=block.latex||block.source||'';return `<div class="formula-block"><div class="formula-kicker">Formula candidate · ${Math.round((block.confidence||0.7)*100)}%</div><div class="formula-render">${mathmlForLatex(latex)}</div><code class="formula-source">\\(${esc(latex)}\\)</code><div class="formula-confidence">识别原文：${esc(block.source||'')}</div></div>`}if(block.type==='table'){const headers=Array.isArray(block.headers)?block.headers:[];const rows=Array.isArray(block.rows)?block.rows:[];const cell=value=>typeof value==='object'&&value!==null?value.value??value.ref??'':value;return `<div class="structured-table"><table>${headers.length?`<thead><tr>${headers.map(value=>`<th>${esc(cell(value))}</th>`).join('')}</tr></thead>`:''}<tbody>${rows.map(row=>`<tr>${(Array.isArray(row)?row:[]).map(value=>`<td>${esc(cell(value))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}if(block.type==='image'){const isSourceImage=/^(PNG|JPG|JPEG|WEBP)$/i.test(String(S.doc?.type||''));const sourceUrl=isSourceImage&&S.doc?.id?`/api/documents/${encodeURIComponent(S.doc.id)}/file`:'';return `<figure class="structured-image"><figcaption class="meta">${esc(block.alt||'Embedded image')}</figcaption>${sourceUrl?`<img class="structured-source-image" src="${sourceUrl}" alt="${esc(block.alt||S.doc?.title||'Learning image')}" loading="lazy" />`:'<div class="image-placeholder">Image/OCR content is indexed; original image preview is preserved in the source document.</div>'}</figure>`}if(block.type==='heading')return `<h3 class="structured-heading">${esc(block.text||'')}</h3>`;if(block.type==='list-item')return `<p class="structured-list-item">• ${esc(block.text||'')}</p>`;if(block.type==='note')return `<aside class="structured-note">${esc(block.text||'')}</aside>`;return `<p>${esc(block.text||'')}</p>`}).join('')}
const renderPageContentBase=renderPageContent;renderPageContent=function(page){const formulaBlocks=(Array.isArray(page?.formulas)&&page.formulas.length?page.formulas:(page?.blocks||[]).filter(block=>block.type==='formula'));let index=0;return renderPageContentBase(page).replace(/(<div class="formula-confidence">[\s\S]*?<\/div>)(<\/div>)/g,(match,confidence,close)=>{const formula=formulaBlocks[index++];if(!formula?.id)return match;return `${confidence}<div class="formula-actions"><button class="tiny-btn" onclick="editFormula('${esc(S.doc?.id)}','${esc(formula.id)}',${Number(page?.page||1)})">修正 LaTeX</button></div>${close}`})};
const renderStructuredContentBase=renderPageContent;renderPageContent=function(page){let html=renderStructuredContentBase(page);for(const block of (page?.blocks||[]).filter(item=>item.type==='vision'&&item.text)){const paragraph=`<p>${esc(block.text)}</p>`;html=html.replace(paragraph,`<aside class="structured-vision"><strong>Vision 识别结果</strong><div>${esc(block.text)}</div></aside>`)}if(/^(PNG|JPG|JPEG|WEBP)$/i.test(String(S.doc?.type||''))){html=html.replace('Image/OCR content is indexed; original image preview is preserved in the source document.',`Image/OCR content is indexed; original image preview is preserved in the source document.<br/><button class="tiny-btn" onclick="analyzeImageDocument('${esc(S.doc?.id||'')}')">使用 Vision 分析图表/公式</button>`)}return html};
const renderMathOcrActionsBase=renderPageContent;renderPageContent=function(page){const html=renderMathOcrActionsBase(page);const enabled=Boolean(S.doc?.sourceFile)&&/^(PDF|PNG|JPG|JPEG|WEBP)$/i.test(String(S.doc?.type||''));if(!enabled)return html;return `<div class="math-ocr-actions"><button class="tiny-btn" onclick="runMathOcr('${esc(S.doc.id)}',${Number(page?.page||1)})">使用专用数学 OCR 重识本页</button><span class="meta">Mathpix · 输出 LaTeX</span></div>${html}`};
function setReaderZoom(value){S.zoom=Math.max(80,Math.min(200,Number(value)||100));if(window.__pdfReader?.setZoom)window.__pdfReader.setZoom(S.zoom/100);else{const paper=document.querySelector('.paper');if(paper)paper.style.zoom=S.zoom/100}}
async function editFormula(documentId, formulaId, page){const pageData=S.pages.find(item=>Number(item.page)===Number(page));const formula=(pageData?.blocks||pageData?.formulas||[]).find(item=>item.id===formulaId);const latex=window.prompt('请确认或修正 LaTeX 公式：',formula?.latex||'');if(latex===null||!latex.trim())return;try{await api(`/api/documents/${encodeURIComponent(documentId)}/formula`,{method:'POST',body:JSON.stringify({page,formulaId,latex:latex.trim()})});toast('公式 LaTeX 已保存，并已更新检索索引');if(S.doc?.id===documentId){S.pages=await api(`/api/documents/${encodeURIComponent(documentId)}/pages`);reader()}}catch(error){toast(error.message)}}
async function analyzeImageDocument(documentId){try{toast('正在调用 Vision 分析图片中的文字、图表和公式…');await api(`/api/documents/${encodeURIComponent(documentId)}/vision`,{method:'POST',body:JSON.stringify({prompt:'请识别这张学习资料图片中的文字、表格、图表和数学公式；使用结构清晰的中文回答，公式尽量使用 LaTeX。'})});S.pages=await api(`/api/documents/${encodeURIComponent(documentId)}/pages`);toast('Vision 结果已保存并加入检索索引');reader()}catch(error){toast(error.message)}}
async function runMathOcr(documentId,page){try{toast('正在调用专用数学 OCR 识别当前页…');const result=await api(`/api/documents/${encodeURIComponent(documentId)}/math-ocr`,{method:'POST',body:JSON.stringify({page:Number(page)||1,persist:true})});S.pages=await api(`/api/documents/${encodeURIComponent(documentId)}/pages`);toast(result.latexCandidates?.length?`Mathpix 已识别 ${result.latexCandidates.length} 个公式并保存 LaTeX`:'Mathpix 未返回可保存的公式，请检查页面裁切或配置');reader()}catch(error){toast(error.message)}}
window.runMathOcr=runMathOcr;
async function installPdfReader(d,p,paper){const viewer=paper.closest('.viewer-wrap');const toolbar=viewer?.querySelector('.viewer-toolbar .toolbar-group:last-child');if(!viewer||!toolbar||toolbar.querySelector('.parsed-view-btn'))return;window.__pdfReader?.destroy?.();window.__pdfReader=null;const button=document.createElement('button');button.className='tiny-btn parsed-view-btn';button.textContent='Parsed view';toolbar.append(button);const surface=document.createElement('div');surface.className='pdf-reader-surface';paper.after(surface);paper.style.display='none';const showParsed=()=>{surface.style.display='none';paper.style.display='block';button.textContent='Original PDF'};const showPdf=()=>{paper.style.display='none';surface.style.display='block';button.textContent='Parsed view'};button.addEventListener('click',()=>{if(surface.style.display==='none')showPdf();else showParsed()});try{const module=await import('/pdf-reader.js');window.__pdfReader=await module.mountPdfReader(surface,{url:`/api/documents/${encodeURIComponent(d.id)}/file`,page:p.page,scale:S.zoom/100,onSelect:selection=>{S.selection=selection.text;S.selectionLatex='';const tools=document.getElementById('tools');if(tools){tools.style.left=`${Math.max(8,selection.rect.left)}px`;tools.style.top=`${Math.max(50,selection.rect.top-38)}px`;tools.classList.add('show')}}});showPdf()}catch(error){surface.remove();paper.style.display='block';toast('PDF.js 阅读器加载失败，已回退到文本视图')}}
function installOriginalLayout(d,p,paper,defaultOriginal=false){const toolbar=document.querySelector('.viewer-toolbar .toolbar-group:last-child');if(!toolbar||toolbar.querySelector('.original-layout-btn'))return;const button=document.createElement('button');button.className='tiny-btn original-layout-btn';button.textContent=defaultOriginal?'Text + LaTeX':'Original layout';toolbar.append(button);let image=null;const loadImage=async()=>{if(!d.sourceFile)return false;if(image)return true;button.disabled=true;try{const response=await fetch(`/api/documents/${encodeURIComponent(d.id)}/page-image/${p.page}`);if(!response.ok)throw new Error('page image unavailable');image=document.createElement('img');image.className='original-page';image.alt=`Original PDF page ${p.page}`;image.src=URL.createObjectURL(await response.blob());paper.after(image);return true}catch(error){toast('原页排版暂时不可用，请确认这是新上传的 PDF');return false}finally{button.disabled=false}};button.addEventListener('click',async()=>{if(!d.sourceFile)return toast('该资料没有保存原始 PDF 文件，请重新上传 PDF');if(await loadImage()){const show=image.style.display!=='block';paper.style.display=show?'none':'block';image.style.display=show?'block':'none';button.textContent=show?'Text + LaTeX':'Original layout'}});if(defaultOriginal)loadImage().then(ok=>{if(ok){paper.style.display='none';image.style.display='block'}})}
const baseReader=reader;reader=function(){baseReader();const d=S.doc,p=S.pages[S.p-1]||S.pages[0],paper=document.querySelector('.paper');if(!paper||!p)return;const label=paper.querySelector('.paper-label');if(d.extraction==='pdf-ocr'&&!paper.querySelector('.page-extraction-note')){const note=document.createElement('div');note.className='page-extraction-note';note.textContent='OCR text and LaTeX are available from Parsed view';label?.after(note)}const paragraphs=paper.querySelectorAll('p');if(paragraphs[0])paragraphs[0].outerHTML=renderPageContent(p);if(d.sourceFile&&d.type==='PDF')installPdfReader(d,p,paper)};
function documentDisplayName(documentRecord){return documentRecord?.metadata?.originalName||documentRecord?.legacy?.metadata?.originalName||documentRecord?.title||'Untitled'}
const outlineFileNameReader=reader;reader=function(){outlineFileNameReader();const host=document.querySelector('.outline');if(host&&!host.querySelector('.outline-file-name'))host.insertAdjacentHTML('afterbegin',`<div class="outline-file-name">${esc(documentDisplayName(S.doc))}</div>`)};
function selectFormula(encodedLatex,page){const latex=decodeURIComponent(encodedLatex||'');if(!latex)return;S.selectionLatex=latex;S.selection=`\\(${latex}\\)`;S.p=Number(page)||S.p;const tools=document.getElementById('tools');if(tools){tools.classList.add('show');tools.style.left='24px';tools.style.top='60px'}toast('公式已选择：后续标注、笔记和 AI 提问将使用 LaTeX')}
const selectablePageContent=renderPageContent;renderPageContent=function(page){const formulas=(page?.blocks||[]).filter(block=>block.type==='formula').length?(page.blocks||[]).filter(block=>block.type==='formula'):(page?.formulas||[]);let index=0;return selectablePageContent(page).replace(/(<div class="formula-confidence">[\s\S]*?<\/div>)/g,(match)=>{const formula=formulas[index++];if(!formula)return match;const encoded=encodeURIComponent(formula.latex||formula.source||'');return `${match}<div class="formula-actions"><button class="tiny-btn" onclick="selectFormula('${encoded}',${Number(page?.page||1)})">选择公式并提问</button></div>`})}
// Some embedded browsers isolate inline handlers from the script lexical scope.
// Delegate the user-facing routes here so navigation remains reliable there too.
document.addEventListener('click',e=>{const el=e.target.closest?.('[onclick]');if(!el)return;const code=el.getAttribute('onclick')||'';let m=code.match(/^go\('([^']+)'(?:,'([^']+)')?\)$/);if(m){e.preventDefault();e.stopImmediatePropagation();go(m[1],m[2]);return}const one={command,render,loadReader,highlight,explain,summarize,card,note,reveal,complete,saveSettings,createLearningCourse,submitLearningCourse,closeCourseCreate,generateReviewQuiz};m=code.match(/^([a-zA-Z]+)\(\)$/);if(m&&one[m[1]]){e.preventDefault();e.stopImmediatePropagation();one[m[1]]()}} ,true);
document.addEventListener('click',e=>{const link=e.target.closest?.('.citation-link');if(!link)return;e.preventDefault();e.stopImmediatePropagation();openCitation(link.dataset.documentId,Number(link.dataset.page||1))},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.command-backdrop')){e.preventDefault();closeCommand();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();command()}});render().then(()=>applyUiLanguage());

// AI integration layer: keep provider selection and streaming behavior outside the reader markup.
function chat(){return `<div class="page-title"><div><div class="eyebrow">Evidence-first tutor · real provider adapter</div><h1>AI Chat</h1><div class="subtitle">选择已配置模型后，问题会通过服务端 Adapter 发送；未配置时明确使用 Local mode。</div></div><span class="mode-pill"><i class="dot"></i> ${currentModelConfig().id?'Configured':'Local mode'}</span></div><div class="card pad" style="max-width:780px">${modelPicker()}<div class="scope">Scope: ${S.doc?esc(S.doc.title):'Entire library'} · Context-aware retrieval</div><div class="messages" style="max-height:500px">${S.messages.map(message).join('')}</div><div class="chat-composer"><textarea id="chat-input" placeholder="Ask about this document…"></textarea><button class="send" onclick="send('chat-input')">↑</button></div></div>`}
const enhancedReaderBase=reader;
reader=function(){enhancedReaderBase();const panel=document.querySelector('.ai-panel');const tabs=panel?.querySelector('.ai-tabs');if(panel&&!panel.querySelector('.ai-model-bar'))tabs?.insertAdjacentHTML('afterend',modelPicker());const tools=document.getElementById('tools');if(tools)tools.innerHTML='<button onclick="askSelected(\'explain\')">解释</button><button onclick="askSelected(\'derive\')">详细推导</button><button onclick="askSelected(\'why\')">为什么</button><button onclick="askSelected(\'relate\')">历史关联</button><button onclick="askSelected(\'quiz\')">生成题目</button><button onclick="highlight()">高亮</button><button onclick="card()">知识卡</button><button onclick="note()">笔记</button>';};
async function askSelected(action='explain'){if(!S.selection)return toast('请先选择 PDF 中的文字');const english=S.settings.language==='en';const prompts={explain:english?'Explain the selected passage clearly.':'请清晰解释选中的内容。',derive:english?'Give a detailed derivation of the selected passage, keeping every important mathematical step.':'请对选中的内容进行详细推导，保留关键数学步骤。',why:english?'Why is the selected statement or method needed?':'为什么需要选中的结论或方法？',relate:english?'Connect the selected passage to my previous learning and explain only meaningful links.':'请将选中的内容与我之前的学习建立有意义的关联，只在确实相关时说明。',quiz:english?'Create one practice question from the selected passage, then give a concise answer and citation.':'请根据选中的内容生成一道练习题，并给出简洁答案和来源引用。'};try{const question=prompts[action]||prompts.explain;const r=await api('/api/chat',{method:'POST',body:JSON.stringify({message:question,documentId:S.doc.id,page:S.p,selectedText:S.selection,formula:S.selectionLatex||undefined,scope:'current-page',language:english?'en':'zh',remember:action!=='quiz',configId:currentModelConfig().id||undefined,sessionId:S.learningSessionId})});S.messages.push({role:'user',text:question+'\n'+S.selection,citations:[]},{role:'assistant',text:r.answer,citations:r.citations||[],memoryAssociations:r.memoryAssociations||[],provider:r.provider,model:r.model});S.tab='Chat';document.getElementById('tools')?.classList.remove('show');reader()}catch(error){toast(error.message)}}
async function readSse(response,onEvent){const reader=response.body?.getReader();if(!reader)throw Error('浏览器不支持流式响应');const decoder=new TextDecoder();let buffer='';while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split(/\r?\n/);buffer=lines.pop()||'';for(const line of lines){if(!line.startsWith('data:'))continue;try{onEvent(JSON.parse(line.slice(5).trim()))}catch{}}}}
send=async function(id){const input=document.getElementById(id);const text=input?.value.trim();if(!text)return;const config=currentModelConfig();const body={message:text,documentId:S.doc?.id, page:S.p, selectedText:S.selection, language:S.settings.language==='en'?'en':'zh', configId:config.id||undefined};input.value='';const user={role:'user',text,selectedText:S.selection,provider:config.provider,model:config.model,citations:[]};S.messages.push(user);const assistant={role:'assistant',text:'',provider:config.provider||'local',model:config.model||'Evidence-first local mode',citations:[]};S.messages.push(assistant);if(S.route==='reading')reader();else render();try{if(config.id&&config.streaming!==false){const response=await fetch('/api/chat/stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw Error(`AI 请求失败 HTTP ${response.status}`);let lastRender=0;await readSse(response,event=>{if(event.error){assistant.text=`${event.error.code||'AI_ERROR'} ${event.error.message||''}`;return}if(event.delta){assistant.text+=event.delta;const now=Date.now();if(now-lastRender>100){lastRender=now;if(S.route==='reading')reader();else render()}}if(event.citations)assistant.citations=event.citations;if(event.provider)assistant.provider=event.provider;if(event.model)assistant.model=event.model});}else{const result=await api('/api/chat',{method:'POST',body:JSON.stringify(body)});assistant.text=result.answer;assistant.citations=result.citations||[];assistant.provider=result.provider;assistant.model=result.model} }catch(error){assistant.text=`${error.message}`;toast(error.message)}if(S.route==='reading')reader();else render()};

function ensureLanguageSetting(){const privacy=document.getElementById('privacy');if(!privacy||document.getElementById('language'))return;const current=S.settings.language==='en'||S.settings.language==='English'?'en':'zh';const row=document.createElement('div');row.className='setting-row';row.innerHTML=`<div><label>Interface / AI language<small>控制工作台界面和本地、远程 AI 的回答语言。</small></label></div><select id="language"><option value="zh" ${current==='zh'?'selected':''}>中文</option><option value="en" ${current==='en'?'selected':''}>English</option></select>`;privacy.closest('.setting-row')?.before(row)}
const renderWithLanguageSetting=render;
render=async function(){await renderWithLanguageSetting();if(S.route==='settings')ensureLanguageSetting()};

