Object.assign(UI_ZH,{Documents:'文档','Questions asked':'提问次数','Concepts':'知识概念','Notes':'笔记','SQLite catalog':'SQLite 资料目录','persistent mastery':'持久化掌握度','in 7 days':'近 7 天','A lightweight view of your actual local learning events.':'基于本地真实学习事件的概览。','Last 7 days · SQLite':'最近 7 天 · SQLite','Weekly questions':'近 7 天提问','Documents with questions':'产生提问的文档','All questions':'全部提问','Daily learning activity':'每日学习活动','questions · notes · annotations':'提问 · 笔记 · 批注','events':'项事件'});
const UI_ZH_RULES=[[/\bpages\b/g,'页'],[/\bPage\b/g,'第'],[/\bNot started\b/g,'尚未开始'],[/\bmin\b/g,'分钟'],[/\btoday\b/gi,'今日'],[/\bneed review\b/gi,'项待复习'],[/\bcards due\b/gi,'张卡片待复习'],[/\bdue Today\b/g,'截止今日'],[/\bdue Tomorrow\b/g,'截止明日'],[/\bRead Chapter\s+(\d+)\b/g,'阅读第 $1 章'],[/^Review (\d+) knowledge cards$/,'复习 $1 张知识卡'],[/^Spaced repetition · (\d+) min$/,'间隔重复 · $1 分钟'],[/^Capture one learning question$/,'记录一个学习问题'],[/^Reflection · (\d+) min$/,'反思 · $1 分钟'],[/^Weekly learning summary$/,'每周学习总结'],[/^StudyAgent · (\d+) min$/,'StudyAgent · $1 分钟'],[/\b(\d+) events\b/g,'$1 项事件']];
function uiLanguage(){return S.settings.language==='en'||S.settings.language==='English'?'en':'zh'}
function applyUiLanguage(){if(uiLanguage()==='en')return;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement?.closest('math,code'))continue;const raw=node.nodeValue||'';const trimmed=raw.trim();if(!trimmed)continue;let next=UI_ZH[trimmed]||trimmed;for(const [pattern,replacement] of UI_ZH_RULES)next=next.replace(pattern,replacement);if(next!==trimmed){const start=raw.indexOf(trimmed);node.nodeValue=raw.slice(0,start)+next+raw.slice(start+trimmed.length)}}for(const el of document.querySelectorAll('[placeholder]')){if(UI_ZH[el.getAttribute('placeholder')])el.setAttribute('placeholder',UI_ZH[el.getAttribute('placeholder')])}for(const el of document.querySelectorAll('[aria-label]')){if(UI_ZH[el.getAttribute('aria-label')])el.setAttribute('aria-label',UI_ZH[el.getAttribute('aria-label')])}document.title='StudyAgent · AI 学习工作台'}
const renderWithUiLanguage=render;
render=async function(){const result=await renderWithUiLanguage();applyUiLanguage();return result};
const readerWithUiLanguage=reader;
reader=function(){const result=readerWithUiLanguage();applyUiLanguage();return result};

const learningFileTypes='.pdf,.docx,.doc,.pptx,.ppt,.md,.markdown,.txt,.xlsx,.xls,.csv,.png,.jpg,.jpeg,.webp';
upload=async function(event){const files=Array.from(event.target.files||[]);if(!files.length)return;const textTypes=/\.(md|markdown|txt|csv)$/i;try{toast(files.length>1?`正在导入 ${files.length} 个文件…`:textTypes.test(files[0].name)?'正在读取文件并建立检索索引…':'正在导入并保留结构…');const payloads=await Promise.all(files.map(async file=>textTypes.test(file.name)?{name:file.name,size:file.size,content:await file.text()}:{name:file.name,size:file.size,base64:await fileBase64(file)}));const courseId=document.getElementById('upload-course')?.value||undefined;const result=payloads.length>1?await api('/api/documents/upload-batch',{method:'POST',body:JSON.stringify({files:payloads,courseId})}):await api('/api/documents/upload',{method:'POST',body:JSON.stringify({...payloads[0],courseId})});const imported=result.documents||[result];S.docs.unshift(...imported);if(result.errors?.length)toast(`已导入 ${imported.length} 个，${result.errors.length} 个失败`);else toast(imported.length>1?`已导入 ${imported.length} 个文件`:`${imported[0]?.title||files[0].name} 已加入 Library`);await render()}catch(error){toast(error.message)}finally{event.target.value=''}};
async function saveLearningSettings(){const language=document.getElementById('language')?.value==='en'?'en':'zh';S.settings=await api('/api/settings',{method:'POST',body:JSON.stringify({language,privacy:document.getElementById('privacy')?.value||'retrieved-chunks',retrievalK:Number(document.getElementById('retrievalK')?.value||8),memoryEnabled:document.getElementById('memoryEnabled')?.checked!==false})});toast('设置已保存');await render()}
async function ensureLearningCourseOptions(){const select=document.getElementById('learning-course');if(!select||select.dataset.loaded)return;try{const courses=await api('/api/courses');select.innerHTML='<option value="">全部课程</option>'+courses.map(course=>`<option value="${esc(course.id)}">${esc(course.name)}</option>`).join('');select.dataset.loaded='1'}catch{select.innerHTML='<option value="">全部课程</option>'}}
async function ensureLearningDocumentOptions(){const select=document.getElementById('learning-documents');if(!select||select.dataset.loaded)return;try{const documents=await api('/api/learning/documents');select.innerHTML=documents.map(item=>`<option value="${esc(item.id)}">${esc(item.title)} · ${esc(item.file_type||'DOC')}</option>`).join('');select.dataset.loaded='1'}catch{select.innerHTML=''} }
async function ensureUploadCourseOptions(){const select=document.getElementById('upload-course');if(!select||select.dataset.loaded)return;try{const courses=await api('/api/courses');select.innerHTML='<option value="">未分类</option>'+courses.filter(course=>course.name!=='未分类').map(course=>`<option value="${esc(course.id)}">${esc(course.name)}</option>`).join('');select.dataset.loaded='1'}catch{select.innerHTML='<option value="">未分类</option>'}}
function learningScopeControls(host){if(!host||host.querySelector('.learning-scope-controls'))return;const english=uiLanguage()==='en';host.insertAdjacentHTML('afterend',`<div class="learning-scope-controls"><label>${english?'Context scope':'上下文范围'}</label><select id="learning-scope"><option value="current-page">${english?'Current page':'当前页面'}</option><option value="current-document" selected>${english?'Current document':'当前文件'}</option><option value="course">${english?'Current course':'当前课程'}</option><option value="documents">${english?'Selected documents':'指定文件'}</option><option value="workspace">${english?'Entire knowledge base':'整个知识库'}</option></select><select id="learning-course" aria-label="${english?'Course scope':'课程范围'}"><option value="">${english?'All courses':'全部课程'}</option></select><select id="learning-documents" aria-label="${english?'Selected documents':'指定文件'}" multiple size="3" style="display:none"></select><label class="memory-turn-control"><input id="learning-remember" type="checkbox" checked /> ${english?'Save this question to long-term memory':'将本次提问保存到长期记忆'}</label></div>`);const scope=document.getElementById('learning-scope');const documents=document.getElementById('learning-documents');scope?.addEventListener('change',()=>{if(documents)documents.style.display=scope.value==='documents'?'block':'none'});ensureLearningCourseOptions();ensureLearningDocumentOptions()}
function memoryPanel(){if(S.route!=='knowledge'||document.getElementById('learning-memory-panel'))return;const anchor=document.querySelector('.knowledge-layout');if(!anchor)return;anchor.insertAdjacentHTML('afterend','<section id="learning-memory-panel" class="card pad learning-memory-panel"><div class="section-head" style="margin-top:0"><div><h2>长期学习记忆</h2><span class="muted">真实保存的问题、概念、薄弱点和历史关联</span></div><div class="memory-actions"><select id="memory-course" aria-label="清空课程记忆"><option value="">选择课程</option></select><button class="btn btn-secondary" onclick="clearLearningCourseMemory()">清空课程记忆</button><button class="btn btn-secondary" onclick="exportLearningMemory()">导出记忆</button></div></div><div id="memory-list" class="memory-list">正在加载记忆…</div></section>');loadMemoryCourses();loadMemoryPanel()}
async function loadMemoryCourses(){const select=document.getElementById('memory-course');if(!select)return;try{const courses=await api('/api/courses');select.innerHTML='<option value="">选择课程</option>'+courses.map(course=>`<option value="${esc(course.id)}">${esc(course.name)}</option>`).join('')}catch(error){select.innerHTML='<option value="">课程加载失败</option>'}}
async function clearLearningCourseMemory(){const courseId=document.getElementById('memory-course')?.value;if(!courseId)return toast('请先选择课程');if(!window.confirm('确定清空该课程的长期记忆吗？此操作不可撤销。'))return;await api(`/api/memory/course?courseId=${encodeURIComponent(courseId)}`,{method:'DELETE'});toast('课程记忆已清空');loadMemoryPanel()}
async function loadMemoryPanel(){const target=document.getElementById('memory-list');if(!target)return;loadMemoryProfile();try{const data=await api('/api/memory');target.innerHTML=`<div class="memory-summary"><span>${data.memories.length} 条记忆</span><span>${data.questions.length} 个历史问题</span><span>${data.concepts.length} 个概念</span><span>${(data.errors||[]).length} 个错误记忆</span></div>`+(data.memories.length?data.memories.map(memory=>`<div class="memory-item"><div class="memory-meta">${esc(memory.type)} · ${esc(memory.updated_at||memory.updatedAt||'')}</div><textarea id="memory-${esc(memory.id)}">${esc(memory.content)}</textarea><div class="memory-actions"><button class="tiny-btn" onclick="saveLearningMemory('${esc(memory.id)}')">保存修改</button><button class="tiny-btn danger" onclick="forgetLearningMemory('${esc(memory.id)}')">删除</button></div></div>`).join(''):'<p class="subtitle">还没有长期记忆。完成一次 AI 提问后，相关问题和概念会在这里出现。</p>')}catch(error){target.textContent=error.message}applyUiLanguage()}
async function loadMemoryProfile(){const list=document.getElementById('memory-list');if(!list)return;let target=document.getElementById('memory-profile');if(!target){target=document.createElement('div');target.id='memory-profile';target.className='memory-profile';list.before(target)}try{const data=await api('/api/memory/profile');const profile=data.profile||{};target.innerHTML=`<div class="memory-profile-head"><div><h3>用户画像记忆</h3><span class="muted">稳定的回答、公式和学习目标偏好会作为 Agent 上下文，可随时修改或清除。</span></div><button class="tiny-btn danger" onclick="forgetLearningProfile()">清除画像</button></div><div class="profile-grid"><label>回答风格<select id="profile-answer-style"><option value="detailed" ${profile.answerStyle!=='concise'?'selected':''}>详细推导</option><option value="concise" ${profile.answerStyle==='concise'?'selected':''}>简洁回答</option></select></label><label>公式表达<select id="profile-formula-style"><option value="latex" ${profile.formulaStyle!=='plain'?'selected':''}>LaTeX</option><option value="plain" ${profile.formulaStyle==='plain'?'selected':''}>线性文本</option></select></label><label>常用编程语言<input id="profile-programming-language" value="${esc(profile.programmingLanguage||'')}" placeholder="例如 Python" /></label><label class="profile-wide">学习目标<textarea id="profile-learning-goals" placeholder="例如：掌握数值线性代数并能独立完成推导">${esc(profile.learningGoals||'')}</textarea></label></div><div class="memory-actions"><button class="btn btn-primary" onclick="saveLearningProfile()">保存用户画像</button></div>`}catch(error){target.textContent=error.message}}
async function saveLearningProfile(){try{const data=await api('/api/memory/profile',{method:'POST',body:JSON.stringify({profile:{answerStyle:document.getElementById('profile-answer-style')?.value,formulaStyle:document.getElementById('profile-formula-style')?.value,programmingLanguage:document.getElementById('profile-programming-language')?.value,learningGoals:document.getElementById('profile-learning-goals')?.value}})});toast('用户画像记忆已保存');loadMemoryProfile();return data}catch(error){toast(error.message)}}
async function forgetLearningProfile(){if(!window.confirm('确定清除用户画像记忆吗？'))return;await api('/api/memory/profile',{method:'DELETE'});toast('用户画像记忆已清除');loadMemoryProfile()}
async function saveLearningMemory(memoryId){const field=document.getElementById(`memory-${memoryId}`);if(!field)return;await api(`/api/memory/${memoryId}`,{method:'POST',body:JSON.stringify({content:field.value,importance:0.6})});toast('记忆已更新');loadMemoryPanel()}
async function forgetLearningMemory(memoryId){await api(`/api/memory/${memoryId}`,{method:'DELETE'});toast('记忆已删除');loadMemoryPanel()}
function exportLearningMemory(){window.location.href='/api/memory/export'}
async function loadNotesPage(){if(S.route!=='notes')return;const host=document.getElementById('notes-list');if(!host)return;try{const data=await api('/api/notes?limit=200');const notes=data.notes||[];host.innerHTML=notes.length?notes.map(noteItem=>{const locator=noteItem.locator||{};const source=noteItem.document_id?`<button class="citation citation-link" type="button" onclick="openCitation('${esc(noteItem.document_id)}',${Number(locator.page)||1})">${esc(noteItem.title||'来源资料')} · ${locator.page?'第'+Number(locator.page)+'页':'打开文档'}</button>`:'<span class="tag">个人笔记</span>';return `<article class="card pad note-card"><div class="section-head" style="margin-top:0"><div><input class="note-title-input" id="note-title-${esc(noteItem.id)}" value="${esc(noteItem.title||'未命名笔记')}" /><div class="meta">${source} · 更新于 ${esc(noteItem.updated_at||'')}</div></div><button class="tiny-btn danger" onclick="deletePersistedNote('${esc(noteItem.id)}')">删除</button></div>${locator.selectedText?`<blockquote class="note-selection">${esc(locator.selectedText)}</blockquote>`:''}<textarea class="note-content-input" id="note-content-${esc(noteItem.id)}">${esc(noteItem.content)}</textarea><div class="memory-actions"><button class="tiny-btn" onclick="updatePersistedNote('${esc(noteItem.id)}')">保存修改</button></div></article>`}).join(''):'<div class="card pad"><p class="subtitle">还没有持久化笔记。阅读资料时选择文字并点击“笔记”，或点击右上角新建笔记。</p></div>'}catch(error){host.innerHTML=`<div class="card pad"><p class="subtitle">无法加载 SQLite 笔记：${esc(error.message)}</p></div>`}applyUiLanguage()}
async function updatePersistedNote(noteId){const title=document.getElementById(`note-title-${noteId}`)?.value.trim()||'';const content=document.getElementById(`note-content-${noteId}`)?.value.trim()||'';if(!content)return toast('笔记内容不能为空');try{await api(`/api/notes/${encodeURIComponent(noteId)}`,{method:'PATCH',body:JSON.stringify({title,content})});toast('笔记已更新');loadNotesPage()}catch(error){toast(error.message)}}
async function deletePersistedNote(noteId){if(!window.confirm('确定删除这条笔记吗？'))return;try{await api(`/api/notes/${encodeURIComponent(noteId)}`,{method:'DELETE'});toast('笔记已删除');loadNotesPage()}catch(error){toast(error.message)}}
function learningDocRow(document){const title=document.title||document.legacy?.title||'Untitled';const type=document.file_type||document.fileType||document.legacy?.type||'DOC';const locator=document.metadata?.pages||document.legacy?.pages||1;const currentCourse=document.course_id||document.courseId||'';const courseOptions=[`<option value="">未分类</option>`,...(S.learningCourses||[]).filter(course=>course.name!=='未分类').map(course=>`<option value="${esc(course.id)}" ${course.id===currentCourse?'selected':''}>${esc(course.name)}</option>`)].join('');return `<div class="doc-row" onclick="go('reading','${esc(document.id)}')" style="cursor:pointer"><div class="doc-icon">${esc(type)}</div><div class="doc-info"><strong>${esc(title)}</strong><span>${esc(type)} · ${esc(locator)} pages · indexed</span></div><select class="course-assignment" aria-label="资料归属课程" onclick="event.stopPropagation()" onchange="reassignLearningDocument('${esc(document.id)}',this.value,event)">${courseOptions}</select><div class="meta">↗</div></div>`}
async function loadCoursesPage(){if(S.route!=='courses'||S.learningCoursesLoading)return;S.learningCoursesLoading=true;try{const [courses,documents,workspaces]=await Promise.all([api('/api/courses'),api('/api/learning/documents'),api('/api/workspaces')]);S.learningCourses=courses;S.learningDocuments=documents;const host=document.getElementById('learning-courses-grid');if(!host)return;host.innerHTML=`<div class="card pad workspace-summary"><div class="section-head" style="margin-top:0"><div><h2>${esc(workspaces[0]?.name||'Personal Workspace')}</h2><span class="muted">${documents.length} structured documents · local SQLite catalog</span></div><span class="tag">${workspaces.length} workspace</span></div><p class="subtitle">资料先归属于 Workspace，再按课程组织；AI 对话可以从这里选择课程范围。</p></div>`+courses.map(course=>{const courseDocs=documents.filter(item=>item.course_id===course.id);return `<section class="card pad"><div class="section-head" style="margin-top:0"><div><h2>${esc(course.name)}</h2><span class="muted">${esc(course.description||'课程资料与长期学习记忆')}</span></div><span class="tag">${courseDocs.length} documents</span></div><div class="progress" style="margin:16px 0 8px"><i style="width:${Math.min(100,courseDocs.length?Math.max(12,courseDocs.length*18):4)}%"></i></div><div class="meta">${courseDocs.length?'已建立结构化检索索引':'暂未导入资料'}</div><div style="margin-top:12px">${courseDocs.length?courseDocs.slice(0,5).map(learningDocRow).join(''):'<p class="subtitle">从资料库上传文件后，可在导入流程中归入该课程。</p>'}</div></section>`}).join('');applyUiLanguage()}catch(error){const host=document.getElementById('learning-courses-grid');if(host)host.innerHTML=`<div class="card pad"><p class="subtitle">${esc(error.message)}</p></div>`}finally{S.learningCoursesLoading=false}}
function createLearningCourse(){if(document.getElementById('course-create-modal'))return;const e=document.createElement('div');e.id='course-create-modal';e.className='modal-backdrop';e.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="course-create-title"><div class="modal-title"><h2 id="course-create-title">新建课程</h2><button class="modal-close" type="button" aria-label="关闭" onclick="closeCourseCreate()">×</button></div><p class="subtitle">课程会保存到当前账号的本地 Workspace。</p><input id="new-course-name" placeholder="例如：数值线性代数" maxlength="120" /><div class="modal-actions"><button class="btn btn-secondary" onclick="closeCourseCreate()">取消</button><button class="btn btn-primary" onclick="submitLearningCourse()">创建课程</button></div></div>`;e.addEventListener('click',event=>{if(event.target===e)closeCourseCreate()});document.body.append(e);document.getElementById('new-course-name')?.focus()}
function closeCourseCreate(){document.getElementById('course-create-modal')?.remove()}
async function submitLearningCourse(){const name=document.getElementById('new-course-name')?.value.trim();if(!name)return toast('请输入课程名称');try{await api('/api/courses',{method:'POST',body:JSON.stringify({name})});closeCourseCreate();toast('课程已创建');await loadCoursesPage()}catch(error){toast(error.message)}}
async function reassignLearningDocument(documentId,courseId,event){event?.stopPropagation();try{await api(`/api/learning/documents/${encodeURIComponent(documentId)}`,{method:'PATCH',body:JSON.stringify({courseId:courseId||null})});toast(courseId?'资料已移动到课程':'资料已恢复为未分类');await loadCoursesPage()}catch(error){toast(error.message);await loadCoursesPage()}}
async function loadKnowledgeGraph(){if(S.route!=='knowledge')return;const host=document.getElementById('knowledge-graph-live');if(!host)return;try{const graph=await api('/api/graph');S.liveGraph=graph;const positions=[[50,50],[16,20],[82,22],[18,72],[82,72],[50,16],[50,82],[30,48]];host.innerHTML=graph.nodes.length?graph.nodes.slice(0,8).map((node,index)=>{const [left,top]=positions[index]||[50,50];return `<button class="node graph-live-node ${index===0?'center':''}" style="left:${left}%;top:${top}%" onclick="showConceptDetails('${esc(node.id)}')">${esc(node.label)}<small>${Math.round((node.mastery||0)*100)}%</small></button>`}).join(''):'<div class="graph-loading">还没有由提问形成的动态概念关系。</div>';const detail=document.getElementById('concept-detail');if(detail&&graph.edges.length)detail.innerHTML=`<div class="meta">${graph.edges.length} 条真实关系：${graph.edges.slice(0,5).map(edge=>`${esc(edge.type)}`).join(' · ')}</div>`}catch(error){host.innerHTML=`<div class="graph-loading">${esc(error.message)}</div>`}}
async function loadKnowledgePoints(){if(S.route!=='knowledge')return;const panel=document.querySelector('.knowledge-layout > .card');if(!panel)return;try{const data=await api('/api/memory');const colors=['#635bff','#2f9e8f','#e58b47','#b45ad6','#3d82c4','#d65f7a'];const concepts=(data.concepts||[]).map((item,index)=>({name:item.name,description:`${item.status||'learning'} · ${item.course_id?'课程概念':'个人学习概念'}`,source:item.metadata?.source||'SQLite learning memory',mastery:Number(item.masteryScore??item.mastery_score??0),color:colors[index%colors.length]})).sort((a,b)=>a.mastery-b.mastery);S.knowledge=concepts;const head=panel.querySelector('.section-head');if(!head)return;panel.innerHTML=`${head.outerHTML}${concepts.length?concepts.map(k=>`<div class="kp-row"><div class="doc-icon" style="background:${k.color}22;color:${k.color}">◇</div><div class="kp-main"><strong>${esc(k.name)}</strong><span>${esc(k.description)} · ${esc(k.source)}</span></div><div class="mastery"><b>${Math.round(k.mastery*100)}%</b><div class="progress"><i style="width:${Math.max(0,Math.min(1,k.mastery))*100}%;background:${k.color}"></i></div></div></div>`).join(''):'<p class="subtitle">还没有持久化概念。完成一次 AI 提问、记录错误或提交复习后，这里会显示真实学习概念。</p>'}`}catch(error){const status=panel.querySelector('.section-head');if(status)panel.innerHTML=`${status.outerHTML}<p class="subtitle">无法加载 SQLite 学习概念：${esc(error.message)}</p>`}}
async function showConceptDetails(conceptId){const detail=document.getElementById('concept-detail');if(!detail)return;detail.innerHTML='<span class="meta">正在加载概念详情…</span>';try{const data=await api(`/api/graph/${encodeURIComponent(conceptId)}`);const concept=data.concept;const sourceText=data.documents.length?data.documents.map(item=>item.title).join('、'):(concept.metadata?.source||'尚无明确来源资料');const progress=data.progress;const progressText=progress?`提问 ${Number(progress.question_count||0)} 次 · 复习 ${Number(progress.review_count||0)} 次 · 正确 ${Number(progress.correct_count||0)} 次`:'尚无学习事件';detail.innerHTML=`<div class="concept-detail-head"><strong>${esc(concept.name)}</strong><span>${Math.round((concept.masteryScore||0)*100)}% · ${esc(concept.status||'learning')}</span></div><p class="subtitle">来源资料：${esc(sourceText)}</p><div class="concept-history"><strong>学习进度</strong><span>${esc(progressText)}</span></div>${data.questions.length?`<div class="concept-history"><strong>历史提问</strong>${data.questions.slice(0,3).map(item=>`<span>• ${esc(item.question)}</span>`).join('')}</div>`:'<div class="concept-history"><span>暂无历史提问</span></div>'}${data.notes?.length?`<div class="concept-history"><strong>相关笔记</strong>${data.notes.slice(0,3).map(item=>`<span>• ${esc(item.title||item.content.slice(0,80))}</span>`).join('')}</div>`:''}${data.cards?.length?`<div class="concept-history"><strong>知识卡 / 练习</strong>${data.cards.slice(0,3).map(item=>`<span>• ${esc(item.front)}</span>`).join('')}</div>`:''}${data.errors?.length?`<div class="concept-history"><strong>错误记忆</strong>${data.errors.slice(0,3).map(item=>`<span>• ${esc(item.description)}</span>`).join('')}</div>`:''}${data.quizAttempts?.length?`<div class="concept-history"><strong>测验记录</strong>${data.quizAttempts.slice(0,3).map(item=>`<span>• ${Number(item.score)}/${Number(item.total)}</span>`).join('')}</div>`:''}<button class="tiny-btn danger" onclick="recordLearningError('${esc(concept.id)}','${esc(concept.name)}')">记录为薄弱点</button>`}catch(error){detail.textContent=error.message}}
async function recordLearningError(conceptId, conceptName){const description=window.prompt(`请描述你在“${conceptName}”上的混淆或错误`);if(!description?.trim())return;const correction=window.prompt('可选：正确理解或纠正方式')||'';try{await api('/api/memory/errors',{method:'POST',body:JSON.stringify({concept:conceptName,description:description.trim(),correction})});toast('错误记忆已保存，掌握度已下调');loadKnowledgeGraph();loadKnowledgePoints()}catch(error){toast(error.message)}}
function applyLearningUi(){const file=document.getElementById('file');if(file)file.setAttribute('accept',learningFileTypes);if(S.route==='settings'){const privacy=document.getElementById('privacy');if(privacy&&!document.getElementById('memoryEnabled')){const row=document.createElement('div');row.className='setting-row';row.innerHTML='<div><label>长期学习记忆<small>允许保存问题、概念关联和薄弱点；可随时关闭。</small></label></div><label class="check-row"><input id="memoryEnabled" type="checkbox" '+(S.settings.memoryEnabled!==false?'checked':'')+'>启用</label>';privacy.closest('.setting-row')?.before(row)} }if(S.route==='library')ensureUploadCourseOptions();if(S.route==='chat')learningScopeControls(document.querySelector('.scope'));if(S.route==='reading')learningScopeControls(document.querySelector('.ai-panel .scope'));if(S.route==='courses')loadCoursesPage();if(S.route==='knowledge')loadKnowledgeGraph();if(S.route==='notes')loadNotesPage();memoryPanel();applyUiLanguage()}
send=async function(id){const input=document.getElementById(id);const text=input?.value.trim();if(!text)return;const config=currentModelConfig();const scope=document.getElementById('learning-scope')?.value||'current-document';const courseId=document.getElementById('learning-course')?.value||undefined;const documentIds=Array.from(document.getElementById('learning-documents')?.selectedOptions||[]).map(option=>option.value);const body={message:text,documentId:S.doc?.id,page:S.p,selectedText:S.selection,formula:S.selectionLatex||undefined,language:S.settings.language==='en'?'en':'zh',scope,courseId,documentIds,remember:document.getElementById('learning-remember')?.checked!==false,conversationId:S.conversationId||undefined,configId:config.id||undefined};input.value='';const assistant={role:'assistant',text:'',provider:config.provider||'local',model:config.model||'Evidence-first local mode',citations:[],memoryAssociations:[]};S.messages.push({role:'user',text,selectedText:S.selection,citations:[]},assistant);if(S.route==='reading')reader();else render();try{if(config.id&&config.streaming!==false){const response=await fetch('/api/chat/stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw Error(`AI 请求失败 HTTP ${response.status}`);await readSse(response,event=>{if(event.conversationId)S.conversationId=event.conversationId;if(event.delta){assistant.text+=event.delta;if(S.route==='reading')reader();else render()}if(event.citations)assistant.citations=event.citations;if(event.memoryAssociations)assistant.memoryAssociations=event.memoryAssociations;if(event.provider)assistant.provider=event.provider;if(event.model)assistant.model=event.model})}else{const result=await api('/api/chat',{method:'POST',body:JSON.stringify(body)});S.conversationId=result.conversationId||S.conversationId;assistant.text=result.answer;assistant.citations=result.citations||[];assistant.memoryAssociations=result.memoryAssociations||[];assistant.provider=result.provider;assistant.model=result.model}}catch(error){assistant.text=error.message;toast(error.message)}if(S.route==='reading')reader();else render()};
const renderWithLearningFeatures=render;
render=async function(){const result=await renderWithLearningFeatures();applyLearningUi();return result};
const readerWithLearningFeatures=reader;
reader=function(){const result=readerWithLearningFeatures();applyLearningUi();return result};
saveSettings=saveLearningSettings;
async function loadLearningProgress(){if(S.route!=='knowledge'||document.getElementById('learning-progress-panel'))return;const anchor=document.querySelector('.knowledge-layout');if(!anchor)return;anchor.insertAdjacentHTML('afterend','<section id="learning-progress-panel" class="card pad learning-progress-panel"><div class="section-head" style="margin-top:0"><div><h2>学习进度</h2><span class="muted">基于真实提问、错误记录和复习事件更新</span></div><span class="tag">SQLite learning_progress</span></div><div id="learning-progress-list" class="progress-list">正在加载学习进度…</div></section>');const target=document.getElementById('learning-progress-list');try{const data=await api('/api/learning/progress');S.learningProgress=data.progress||[];target.innerHTML=S.learningProgress.length?S.learningProgress.map(item=>`<div class="progress-entry"><div><strong>${esc(item.concept_name)}</strong><small>${esc(item.last_event||'question')} · ${item.question_count||0} 次提问 · ${item.review_count||0} 次复习 · ${item.attempts||0} 次尝试</small></div><div class="progress-score">${Math.round((S.knowledge.find(k=>k.name===item.concept_name)?.mastery||0)*100)}%</div></div>`).join(''):'<p class="subtitle">还没有学习事件。完成一次 AI 提问或记录薄弱点后，这里会显示真实进度。</p>'}catch(error){target.textContent=error.message}}
async function loadDailyLearningSummary(){const target=document.getElementById('learning-summary-content');if(!target)return;try{const data=await api('/api/learning/summary');const en=uiLanguage()==='en';target.innerHTML=`<div class="agent-summary-grid"><div><strong>${en?'Questions today':'今日提问'}</strong><span>${data.questionsToday}</span></div><div><strong>${en?'Weak concepts':'薄弱概念'}</strong><span>${data.weakConcepts.length}</span></div><div><strong>${en?'Errors today':'今日错误'}</strong><span>${data.errorsToday}</span></div></div><p class="subtitle">${data.learned.length?(en?'Learned: ':'今天学习：')+data.learned.map(item=>esc(item.name)).join(' · '):(en?'No learning event recorded today.':'今天还没有记录到新的学习事件。')}</p>${data.associations.length?`<p class="meta">${en?'Relations: ':'知识关联：'}${data.associations.slice(0,4).map(item=>`${esc(item.source)} → ${esc(item.target)}`).join(' · ')}</p>`:''}`}catch(error){target.textContent=error.message}}
async function generateLearningQuiz(){const target=document.getElementById('learning-quiz-content');if(!target)return;const concept=window.prompt(uiLanguage()==='en'?'Optional concept for the quiz:':'可选：想复习哪个概念？')||'';target.innerHTML='<span class="meta">正在根据真实资料生成复习题…</span>';try{const data=await api('/api/learning/quiz',{method:'POST',body:JSON.stringify({concept,count:3})});target.innerHTML=`<div class="meta">${esc(data.topic)} · ${esc(data.mode)}</div>${data.items.length?data.items.map((item,index)=>`<details class="quiz-item"><summary>${index+1}. ${esc(item.question)}</summary><div class="quiz-answer">${renderAiText(normalizeReviewFormulaText(item.answer,item))}</div>${citationMarkup({id:index+1,documentId:item.documentId,locator:item.locator,label:item.citation},index+1)}</details>`).join(''):'<p class="subtitle">当前范围没有可生成题目的检索证据。</p>'}`}catch(error){target.textContent=error.message}}
function loadLearningAgents(){if(S.route!=='knowledge'||document.getElementById('learning-agents-panel'))return;const anchor=document.getElementById('learning-progress-panel')||document.querySelector('.knowledge-layout');if(!anchor)return;const en=uiLanguage()==='en';anchor.insertAdjacentHTML('afterend',`<section id="learning-agents-panel" class="card pad learning-agents-panel"><div class="section-head" style="margin-top:0"><div><h2>${en?'Learning agents':'学习 Agent'}</h2><span class="muted">${en?'Generated from persisted learning memory and retrieved evidence':'基于持久化学习记忆和检索证据生成'}</span></div><div class="memory-actions"><button class="btn btn-secondary" onclick="loadDailyLearningSummary()">${en?'Today summary':'今日学习总结'}</button><button class="btn btn-primary" onclick="generateLearningQuiz()">${en?'Generate quiz':'生成复习题'}</button></div></div><div id="learning-summary-content" class="agent-output"><span class="meta">${en?'Click Today summary to load real data.':'点击“今日学习总结”加载真实数据。'}</span></div><div id="learning-quiz-content" class="agent-output"><span class="meta">${en?'Quiz answers will cite source sections.':'复习题答案会保留来源区段引用。'}</span></div></section>`)}
function renderQuizAttempt(){const target=document.getElementById('learning-quiz-content');if(!target||!S.quizItems.length)return;target.innerHTML=`<div class="meta">${esc(S.quizTopic||'当前资料')} · retrieval-grounded-local</div>${S.quizItems.map((item,index)=>`<div class="quiz-item"><div class="quiz-type">${esc(item.typeLabel||item.type||'综合题')}</div><div class="quiz-question">${index+1}. ${esc(item.question)}</div><details><summary>查看答案与来源证据</summary><div class="quiz-answer">${renderAiText(item.answer)}</div>${citationMarkup({id:index+1,documentId:item.documentId,locator:item.locator,label:item.citation},index+1)}</details><div class="quiz-actions"><button class="tiny-btn ${S.quizAnswers[index]===true?'selected':''}" onclick="recordQuizAnswer(${index},true)">记住了</button><button class="tiny-btn ${S.quizAnswers[index]===false?'selected':''}" onclick="recordQuizAnswer(${index},false)">需要复习</button></div></div>`).join('')}<button class="btn btn-primary" onclick="submitQuizAttempt()">提交本次复习</button>`}
async function generateReviewQuiz(){const target=document.querySelector('#review-self-test .agent-output');if(!target)return;target.innerHTML='<span class="meta">正在从全部学习资料生成多样自测题…</span>';try{const data=await api('/api/learning/quiz',{method:'POST',body:JSON.stringify({count:6,language:uiLanguage()==='en'?'en':'zh'})});const items=data.items||[];target.innerHTML=items.length?`<div class="meta">${esc(data.topic||'当前资料')} · ${esc(data.mode||'retrieval-grounded-local')}</div>${items.map((item,index)=>`<article class="review-quiz-item"><div class="quiz-type">${esc(item.typeLabel||item.type||'综合题')}</div><h3>${index+1}. ${esc(item.question)}</h3><details><summary>查看答案与来源</summary><div class="quiz-answer">${renderAiText(item.answer)}</div>${citationMarkup({id:index+1,documentId:item.documentId,locator:item.locator,label:item.citation},index+1)}</details></article>`).join('')}`:'<p class="subtitle">当前资料库没有足够的检索证据。</p>'}catch(error){target.textContent=error.message}}
function recordQuizAnswer(index,correct){S.quizAnswers[index]=Boolean(correct);renderQuizAttempt()}
async function submitQuizAttempt(){if(!S.quizItems.length)return;if(S.quizAnswers.length<S.quizItems.length||S.quizAnswers.some(value=>typeof value!=='boolean')){toast('请先完成每一道复习题');return}try{const result=await api('/api/learning/quiz/attempt',{method:'POST',body:JSON.stringify({concept:S.quizItems[0].topic,answers:S.quizItems.map((item,index)=>({question:item.question,citation:item.citation,correct:S.quizAnswers[index]}))})});toast(`复习已记录：${result.score}/${result.total}`);loadLearningProgress();loadMemoryPanel()}catch(error){toast(error.message)}}
async function generateLearningQuizV2(){const target=document.getElementById('learning-quiz-content');if(!target)return;const concept='';target.innerHTML='<span class="meta">正在根据真实资料生成 6 道多样复习题…</span>';try{const data=await api('/api/learning/quiz',{method:'POST',body:JSON.stringify({concept,count:6,language:uiLanguage()==='en'?'en':'zh'})});S.quizItems=data.items||[];S.quizTopic=data.topic||concept||'';S.quizAnswers=[];renderQuizAttempt();if(!S.quizItems.length)target.innerHTML='<p class="subtitle">当前范围没有可生成题目的检索证据。</p>'}catch(error){target.textContent=error.message}}
generateLearningQuiz=generateLearningQuizV2;
async function ensurePromptSettings(){if(S.promptSettings)return S.promptSettings;try{const data=await api('/api/prompt/settings');S.promptSettings=data.settings||{};return S.promptSettings}catch(error){console.warn('prompt settings unavailable',error);return {}}}
function promptModelOptions(selected=''){return `<option value="">${uiLanguage()==='en'?'Local structured optimizer':'本地结构化优化'}</option>${S.modelConfigs.filter(config=>!isMathOcrModel(config)).map(config=>`<option value="${esc(config.id)}" ${config.id===selected?'selected':''}>${esc(config.providerName||config.provider)} · ${esc(config.model)}${config.hasApiKey?'':'（未配置 Key）'}</option>`).join('')}`}
function promptOptimizationPanel(){if(S.route!=='settings'||document.getElementById('prompt-optimization-settings'))return;ensurePromptSettings().then(settings=>{if(document.getElementById('prompt-optimization-settings'))return;const anchor=document.querySelector('.settings');if(!anchor)return;anchor.insertAdjacentHTML('afterend',`<div id="prompt-optimization-settings" class="card pad settings" style="margin-top:16px"><div class="section-head" style="margin-top:0"><div><h2>Prompt 优化与记忆增强</h2><span class="muted">先理解问题，再按相关性组合资料、历史问题和学习薄弱点。</span></div><span class="tag">真实检索 · SQLite</span></div><div class="setting-row"><div><label>优化级别<small>关闭、按问题自动判断，或始终优化。</small></label></div><select id="promptLevel"><option value="off" ${settings.level==='off'?'selected':''}>关闭</option><option value="automatic" ${settings.level==='automatic'?'selected':''}>自动</option><option value="always" ${settings.level==='always'?'selected':''}>始终优化</option></select></div><div class="setting-row"><div><label>回答模式<small>影响最终 Prompt 的结构，不会暴露模型隐藏推理。</small></label></div><select id="promptAnswerMode"><option value="quick" ${settings.answerMode==='quick'?'selected':''}>快速回答</option><option value="detailed" ${settings.answerMode==='detailed'?'selected':''}>详细解释</option><option value="study" ${settings.answerMode==='study'?'selected':''}>学习模式</option><option value="exam" ${settings.answerMode==='exam'?'selected':''}>考试模式</option><option value="socratic" ${settings.answerMode==='socratic'?'selected':''}>苏格拉底模式</option></select></div><div class="setting-row"><div><label>Prompt 优化模型<small>可与最终回答模型分开；未配置时使用本地结构化优化。</small></label></div><select id="promptOptimizerConfig">${promptModelOptions(settings.optimizerConfigId||'')}</select></div><div class="setting-row"><div><label>最终回答模型<small>选择用于生成答案的模型配置。</small></label></div><select id="promptAnswerConfig">${promptModelOptions(settings.answerConfigId||'')}</select></div><div class="setting-row"><div><label>上下文来源<small>只纳入勾选的数据类别，且会按相关性阈值去重。</small></label></div><div class="prompt-checks"><label class="check-row"><input id="promptMemory" type="checkbox" ${settings.includeMemory!==false?'checked':''}>长期记忆</label><label class="check-row"><input id="promptDocument" type="checkbox" ${settings.includeDocument!==false?'checked':''}>当前资料</label><label class="check-row"><input id="promptConversation" type="checkbox" ${settings.includeConversation!==false?'checked':''}>近期对话</label><label class="check-row"><input id="promptKnowledge" type="checkbox" ${settings.includeKnowledge!==false?'checked':''}>知识关联</label></div></div><div class="setting-row"><div><label>提问前预览<small>发送前显示结构化 Prompt，可编辑后选择使用优化版或原始问题。</small></label></div><label class="check-row"><input id="promptPreview" type="checkbox" ${settings.showPreview?'checked':''}>启用预览</label></div><div class="setting-row"><div><label>开发日志<small>默认隐藏；开启后才允许查看优化链路日志。</small></label></div><label class="check-row"><input id="promptDevLogs" type="checkbox" ${settings.developmentLogs?'checked':''}>记录日志</label></div><div class="model-actions"><button class="btn btn-primary" onclick="savePromptOptimizationSettings()">保存 Prompt 设置</button></div><div id="prompt-settings-status" class="model-status">${settings.developmentLogs?'开发日志已启用。':'优化链路日志默认隐藏。'}</div></div>`)}).catch(error=>console.warn(error))}
async function savePromptOptimizationSettings(){try{S.promptSettings=await api('/api/prompt/settings',{method:'POST',body:JSON.stringify({level:document.getElementById('promptLevel')?.value,answerMode:document.getElementById('promptAnswerMode')?.value,optimizerConfigId:document.getElementById('promptOptimizerConfig')?.value||null,answerConfigId:document.getElementById('promptAnswerConfig')?.value||null,includeMemory:document.getElementById('promptMemory')?.checked,includeDocument:document.getElementById('promptDocument')?.checked,includeConversation:document.getElementById('promptConversation')?.checked,includeKnowledge:document.getElementById('promptKnowledge')?.checked,showPreview:document.getElementById('promptPreview')?.checked,developmentLogs:document.getElementById('promptDevLogs')?.checked})}).then(data=>data.settings);toast('Prompt 优化设置已保存')}catch(error){toast(error.message)}}
function renderPromptPreview(preview){const editor=esc(preview.optimizedPrompt||preview.originalPrompt||'');const host=document.querySelector('.chat-composer');if(!host)return;document.getElementById('prompt-preview')?.remove();host.insertAdjacentHTML('beforebegin',`<div id="prompt-preview" class="prompt-preview card"><div class="section-head" style="margin-top:0"><div><strong>Prompt 已优化</strong><span class="muted">${esc(preview.queryType||'other')} · ${esc(preview.mode||'local-fallback')} · 已选 ${Number(preview.memories?.selected?.length||0)} 条记忆</span></div><button class="tiny-btn" onclick="cancelPromptPreview()">取消</button></div><textarea id="prompt-preview-editor">${editor}</textarea><div class="prompt-preview-actions"><button class="btn btn-secondary" onclick="choosePromptVersion('original')">使用原始问题</button><button class="btn btn-primary" onclick="choosePromptVersion('optimized')">使用优化 Prompt</button></div></div>`)}
function cancelPromptPreview(){S.pendingPrompt=null;document.getElementById('prompt-preview')?.remove()}
async function choosePromptVersion(version){const pending=S.pendingPrompt;if(!pending)return;const selected=version==='optimized'?(document.getElementById('prompt-preview-editor')?.value||pending.preview.optimizedPrompt):pending.preview.originalPrompt;const input=document.getElementById(pending.inputId);if(input)input.value='';document.getElementById('prompt-preview')?.remove();S.pendingPrompt=null;try{const result=await api('/api/chat',{method:'POST',body:JSON.stringify({...pending.body,skipOptimization:true,optimizedPromptOverride:selected})});S.conversationId=result.conversationId||S.conversationId;S.messages.push({role:'user',text:pending.body.message,selectedText:pending.body.selectedText,citations:[]},{role:'assistant',text:result.answer,citations:result.citations||[],memoryAssociations:result.memoryAssociations||[],provider:result.provider,model:result.model});if(S.route==='reading')reader();else render()}catch(error){toast(error.message)}}
window.choosePromptVersion=choosePromptVersion;window.cancelPromptPreview=cancelPromptPreview;window.savePromptOptimizationSettings=savePromptOptimizationSettings;
const sendWithoutPromptPreview=send;
send=async function(id){const settings=await ensurePromptSettings();if(!settings.showPreview||S.pendingPromptOverride)return sendWithoutPromptPreview(id);const input=document.getElementById(id);const text=input?.value.trim();if(!text)return;const config=currentModelConfig();const body={message:text,documentId:S.doc?.id,page:S.p,selectedText:S.selection,language:S.settings.language==='en'?'en':'zh',scope:document.getElementById('learning-scope')?.value||'current-document',courseId:document.getElementById('learning-course')?.value||undefined,documentIds:Array.from(document.getElementById('learning-documents')?.selectedOptions||[]).map(option=>option.value),remember:document.getElementById('learning-remember')?.checked!==false,conversationId:S.conversationId||undefined,configId:config.id||undefined};try{const preview=await api('/api/prompt/optimize',{method:'POST',body:JSON.stringify(body)});S.pendingPrompt={inputId:id,body,preview};renderPromptPreview(preview)}catch(error){toast(error.message)}};
const applyLearningUiWithPromptSettings=applyLearningUi;
applyLearningUi=function(){const result=applyLearningUiWithPromptSettings();if(S.route==='settings'){promptOptimizationPanel();mathOcrPanel()}return result};
const applyLearningUiWithProgress=applyLearningUi;
applyLearningUi=function(){const result=applyLearningUiWithProgress();if(S.route==='knowledge'){loadKnowledgePoints();loadLearningProgress();loadLearningAgents()}return result};
const applyLearningUiWithProviderBoundary=applyLearningUi;
applyLearningUi=function(){const result=applyLearningUiWithProviderBoundary();if(S.route==='settings'){document.querySelector('#modelProvider option[value="mathpix"]')?.remove()}return result};
// Initial rendering is triggered after account/session wiring below.

function account() {
  const en = uiLanguage() === 'en';
  const user = S.auth?.user;
  if (!user || S.auth?.guest) return `<div class="page-title"><div><div class="eyebrow">Personal account · local-first</div><h1>${en ? 'Sign in to StudyAgent' : '登录 StudyAgent 个人账号'}</h1><div class="subtitle">${en ? 'Guest mode remains available. Sign in to keep your documents, memory and model settings separated across sessions.' : '游客模式仍可使用；登录后，文档、长期记忆和模型设置会按账号隔离并跨会话保存。'}</div></div><span class="mode-pill"><i class="dot"></i> ${en ? 'Guest mode' : '游客模式'}</span></div><div class="account-grid"><section class="card pad account-card"><h2>${en ? 'Login' : '登录'}</h2><label>Email<input id="account-login-email" type="email" autocomplete="email" /></label><label>${en ? 'Password' : '密码'}<input id="account-login-password" type="password" autocomplete="current-password" /></label><button class="btn btn-primary" onclick="accountLogin()">${en ? 'Login' : '登录'}</button><div id="account-status" class="model-status"></div></section><section class="card pad account-card"><h2>${en ? 'Create account' : '注册账号'}</h2><label>${en ? 'Display name' : '用户名'}<input id="account-register-name" autocomplete="name" /></label><label>Email<input id="account-register-email" type="email" autocomplete="email" /></label><label>${en ? 'Password (8+ characters)' : '密码（至少 8 位）'}<input id="account-register-password" type="password" autocomplete="new-password" /></label><button class="btn btn-secondary" onclick="accountRegister()">${en ? 'Register' : '注册'}</button><p class="subtitle">${en ? 'Passwords are hashed on the local server. API keys are never returned to the browser in plaintext.' : '密码只在本地服务端进行哈希处理；API Key 不会以明文返回给浏览器。'}</p></section></div>`;
  return `<div class="page-title"><div><div class="eyebrow">Personal account · ${esc(user.email)}</div><h1>${en ? `Welcome, ${esc(user.username)}` : `你好，${esc(user.username)}`}</h1><div class="subtitle">${en ? 'Your learning records are scoped to this account.' : '当前文档、课程、对话、记忆和模型配置均归属于当前账号。'}</div></div><span class="mode-pill"><i class="dot"></i> ${en ? 'Account mode' : '个人账号模式'}</span></div><div class="account-grid"><section class="card pad account-card"><div class="section-head" style="margin-top:0"><h2>${en ? 'Profile' : '个人资料'}</h2><span class="tag">${esc(user.email)}</span></div><label>${en ? 'Display name' : '用户名'}<input id="account-profile-name" value="${esc(user.username)}" maxlength="120" /></label><label>Email<input value="${esc(user.email)}" disabled /></label><button class="btn btn-primary" onclick="saveAccountProfile()">${en ? 'Save profile' : '保存资料'}</button><div id="account-status" class="model-status"></div></section><section class="card pad account-card"><div class="section-head" style="margin-top:0"><h2>${en ? 'Session & data' : '会话与数据'}</h2><span class="tag">SQLite</span></div><p class="subtitle">${en ? 'Export the data owned by this account, or sign out on this device.' : '可导出当前账号拥有的学习数据，也可以退出当前设备。'}</p><div class="account-actions"><button class="btn btn-secondary" onclick="exportAccountData()">${en ? 'Export my data' : '导出我的数据'}</button><button class="btn btn-secondary" onclick="accountLogout()">${en ? 'Log out' : '退出登录'}</button></div></section><section class="card pad account-card"><h2>${en ? 'Change password' : '修改密码'}</h2><label>${en ? 'Current password' : '当前密码'}<input id="account-current-password" type="password" autocomplete="current-password" /></label><label>${en ? 'New password' : '新密码'}<input id="account-new-password" type="password" autocomplete="new-password" /></label><button class="btn btn-secondary" onclick="changeAccountPassword()">${en ? 'Update password' : '更新密码'}</button></section><section class="card pad account-card danger-card"><h2>${en ? 'Delete account' : '删除账号'}</h2><p class="subtitle">${en ? 'This permanently deletes this account and its documents, conversations, memory, notes and learning graph.' : '此操作会永久删除账号及其文档、对话、长期记忆、笔记和学习图谱。'}</p><button class="btn btn-danger" onclick="deleteAccountPermanently()">${en ? 'Delete account' : '永久删除账号'}</button></section></div>`;
}

function resetAccountScopedCache() { S.docs=[]; S.doc=null; S.ann=[]; S.knowledge=[]; S.cards=[]; S.reviews=[]; S.analytics=null; S.messages=[]; S.settings={}; S.modelConfigs=[]; S.modelProviders=[]; S.promptSettings=null; S.conversationId=''; S.learningSessionId=''; S.learningSessionDocumentId=''; }
async function loadAuthSession() { try { S.auth=await api('/api/auth/session'); } catch { S.auth={ guest:true, authenticated:false, user:{ username:'Guest' } }; } }
function accountMessage(message) { const target=document.getElementById('account-status'); if(target) target.textContent=message; else toast(message); }
async function accountLogin() { try { const result=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:document.getElementById('account-login-email')?.value,password:document.getElementById('account-login-password')?.value})}); S.auth=result; resetAccountScopedCache(); toast('已登录，已切换到个人数据空间'); await render(); } catch(error) { accountMessage(error.message); } }
async function accountRegister() { try { const result=await api('/api/auth/register',{method:'POST',body:JSON.stringify({username:document.getElementById('account-register-name')?.value,email:document.getElementById('account-register-email')?.value,password:document.getElementById('account-register-password')?.value})}); S.auth=result; resetAccountScopedCache(); toast('账号已创建'); await render(); } catch(error) { accountMessage(error.message); } }
async function accountLogout() { try { await api('/api/auth/logout',{method:'POST'}); S.auth=null; resetAccountScopedCache(); await loadAuthSession(); toast('已退出登录，当前为游客模式'); await render(); } catch(error) { accountMessage(error.message); } }
async function saveAccountProfile() { try { const result=await api('/api/account',{method:'PATCH',body:JSON.stringify({username:document.getElementById('account-profile-name')?.value})}); S.auth.user=result.user; toast('个人资料已保存'); await render(); } catch(error) { accountMessage(error.message); } }
async function changeAccountPassword() { try { await api('/api/account/password',{method:'POST',body:JSON.stringify({currentPassword:document.getElementById('account-current-password')?.value,newPassword:document.getElementById('account-new-password')?.value})}); toast('密码已更新'); } catch(error) { accountMessage(error.message); } }
function exportAccountData() { window.location.href='/api/account/export'; }
async function deleteAccountPermanently() { if(!window.confirm('确定永久删除当前账号及其全部学习数据吗？'))return; const confirmation=window.prompt('请输入 DELETE 确认'); if(confirmation!=='DELETE')return toast('未完成删除确认'); try { await api('/api/account',{method:'DELETE',body:JSON.stringify({confirmation})}); S.auth=null; resetAccountScopedCache(); await loadAuthSession(); toast('账号及其数据已删除'); await render(); } catch(error) { accountMessage(error.message); } }
window.accountLogin=accountLogin;window.accountRegister=accountRegister;window.accountLogout=accountLogout;window.saveAccountProfile=saveAccountProfile;window.changeAccountPassword=changeAccountPassword;window.deleteAccountPermanently=deleteAccountPermanently;window.exportAccountData=exportAccountData;
const renderWithAccount=render;
render=async function(){if(!S.auth)await loadAuthSession();await renderWithAccount();if(S.route==='account'&&S.auth?.guest===false)document.querySelector('.account-card input')?.focus();};
function renderGraphManagement(graph) { const host=document.getElementById('graph-management'); if(!host)return; const nodes=graph.nodes||[]; const edges=graph.edges||[]; const types=['RELATED_TO','PREREQUISITE_OF','DERIVED_FROM','ASKED_ABOUT','MENTIONED_IN','CONFUSED_WITH','SOLVED_BY','BELONGS_TO']; host.innerHTML=`<div class="graph-management-head"><div><strong>关系管理</strong><span class="muted">新增或删除当前账号的概念关系，立即写入 SQLite。</span></div><span class="tag">${edges.length} 条关系</span></div>${nodes.length>=2?`<div class="graph-relation-form"><select id="graph-source"><option value="">源概念</option>${nodes.map(node=>`<option value="${esc(node.id)}">${esc(node.label)}</option>`).join('')}</select><select id="graph-type">${types.map(type=>`<option value="${type}">${type}</option>`).join('')}</select><select id="graph-target"><option value="">目标概念</option>${nodes.map(node=>`<option value="${esc(node.id)}">${esc(node.label)}</option>`).join('')}</select><button class="tiny-btn" onclick="saveGraphRelation()">添加关系</button></div>`:'<p class="subtitle">至少需要两个持久化概念后才能建立关系。</p>'}<div class="graph-edge-list">${edges.length?edges.map(edge=>`<div class="graph-edge-row"><span>${esc(edge.sourceLabel||edge.source)}</span><b>${esc(edge.type)}</b><span>${esc(edge.targetLabel||edge.target)}</span><button class="tiny-btn danger" onclick="deleteGraphRelation('${esc(edge.id)}')">删除</button></div>`).join(''):'<span class="meta">还没有可管理的概念关系。</span>'}</div>`; }
async function saveGraphRelation(){const sourceId=document.getElementById('graph-source')?.value;const targetId=document.getElementById('graph-target')?.value;const type=document.getElementById('graph-type')?.value;if(!sourceId||!targetId)return toast('请选择源概念和目标概念');if(sourceId===targetId)return toast('源概念和目标概念不能相同');try{await api('/api/graph/relations',{method:'POST',body:JSON.stringify({sourceId,targetId,type,weight:0.6})});toast('概念关系已保存');await loadKnowledgeGraph()}catch(error){toast(error.message)}}
async function deleteGraphRelation(relationId){if(!window.confirm('确定删除这条概念关系吗？'))return;try{await api(`/api/graph/relations/${encodeURIComponent(relationId)}`,{method:'DELETE'});toast('概念关系已删除');await loadKnowledgeGraph()}catch(error){toast(error.message)}}
window.saveGraphRelation=saveGraphRelation;window.deleteGraphRelation=deleteGraphRelation;
loadKnowledgeGraph=async function(){if(S.route!=='knowledge')return;const host=document.getElementById('knowledge-graph-live');if(!host)return;try{const graph=await api('/api/graph');S.liveGraph=graph;const positions=[[50,50],[16,20],[82,22],[18,72],[82,72],[50,16],[50,82],[30,48]];host.innerHTML=graph.nodes.length?graph.nodes.slice(0,8).map((node,index)=>{const [left,top]=positions[index]||[50,50];return `<button class="node graph-live-node ${index===0?'center':''}" style="left:${left}%;top:${top}%" onclick="showConceptDetails('${esc(node.id)}')">${esc(node.label)}<small>${Math.round((node.mastery||0)*100)}%</small></button>`}).join(''):'<div class="graph-loading">还没有由提问形成的动态概念关系。</div>';const detail=document.getElementById('concept-detail');if(detail&&graph.edges.length)detail.innerHTML=`<div class="meta">${graph.edges.length} 条真实关系：${graph.edges.slice(0,5).map(edge=>`${esc(edge.sourceLabel||edge.source)} ${esc(edge.type)} ${esc(edge.targetLabel||edge.target)}`).join(' · ')}</div>`;renderGraphManagement(graph)}catch(error){host.innerHTML=`<div class="graph-loading">${esc(error.message)}</div>`;renderGraphManagement({nodes:[],edges:[]})}};
render();

const loadCoursesPageWithLearningStats=loadCoursesPage;
 loadCoursesPage=async function(){await loadCoursesPageWithLearningStats();if(S.route!=='courses')return;const sections=[...document.querySelectorAll('#learning-courses-grid section.card')];const stats=await Promise.all((S.learningCourses||[]).map(async course=>{try{const [memory,notes,knowledge,progress]=await Promise.all([api(`/api/memory?courseId=${encodeURIComponent(course.id)}&limit=200`),api(`/api/notes?courseId=${encodeURIComponent(course.id)}&limit=200`),api(`/api/knowledge?courseId=${encodeURIComponent(course.id)}&limit=200`),api(`/api/learning/progress?courseId=${encodeURIComponent(course.id)}&limit=200`)]);return {memories:(memory.memories||[]).length,questions:(memory.questions||[]).length,concepts:(memory.concepts||[]).length,errors:(memory.errors||[]).length,notes:(notes.notes||[]).length,cards:(knowledge.cards||[]).length,progress:(progress.progress||[]).length}}catch{return {memories:0,questions:0,concepts:0,errors:0,notes:0,cards:0,progress:0}}}));const en=uiLanguage()==='en';for(const [index,summary] of stats.entries()){const section=sections[index];if(!section)continue;section.querySelector('.course-learning-summary')?.remove();section.insertAdjacentHTML('beforeend',`<div class="course-learning-summary"><div class="course-summary-title">${en?'Learning objects':'学习对象'}</div><div class="course-summary-grid"><span>${en?'Notes':'笔记'} <b>${summary.notes}</b></span><span>${en?'Questions':'问题'} <b>${summary.questions}</b></span><span>${en?'Concepts':'概念'} <b>${summary.concepts}</b></span><span>${en?'Memories':'记忆'} <b>${summary.memories}</b></span><span>${en?'Cards':'知识卡'} <b>${summary.cards}</b></span><span>${en?'Errors':'错误'} <b>${summary.errors}</b></span><span>${en?'Progress records':'进度记录'} <b>${summary.progress}</b></span></div></div>`)}applyUiLanguage()};
 loadCoursesPage=async function(){await loadCoursesPageWithLearningStats();if(S.route!=='courses')return;const sections=[...document.querySelectorAll('#learning-courses-grid section.card')];const stats=await Promise.all((S.learningCourses||[]).map(async course=>{try{const [memory,notes,knowledge,progress]=await Promise.all([api(`/api/memory?courseId=${encodeURIComponent(course.id)}&limit=200`),api(`/api/notes?courseId=${encodeURIComponent(course.id)}&limit=200`),api(`/api/knowledge?courseId=${encodeURIComponent(course.id)}&limit=200`),api(`/api/learning/progress?courseId=${encodeURIComponent(course.id)}&limit=200`)]);return {memories:(memory.memories||[]).length,questions:(memory.questions||[]).length,concepts:(memory.concepts||[]).length,errors:(memory.errors||[]).length,notes:(notes.notes||[]).length,cards:(knowledge.cards||[]).length,progress:(progress.progress||[]).length}}catch{return {memories:0,questions:0,concepts:0,errors:0,notes:0,cards:0,progress:0}}}));const en=uiLanguage()==='en';for(const [index,summary] of stats.entries()){const section=sections[index];if(!section)continue;section.querySelector('.course-learning-summary')?.remove();section.insertAdjacentHTML('beforeend',`<div class="course-learning-summary"><div class="course-summary-title">${en?'Learning objects':'学习对象'}</div><div class="course-summary-grid"><span>${en?'Notes':'笔记'} <b>${summary.notes}</b></span><span>${en?'Questions':'问题'} <b>${summary.questions}</b></span><span>${en?'Concepts':'概念'} <b>${summary.concepts}</b></span><span>${en?'Memories':'记忆'} <b>${summary.memories}</b></span><span>${en?'Cards':'知识卡'} <b>${summary.cards}</b></span><span>${en?'Errors':'错误'} <b>${summary.errors}</b></span><span>${en?'Progress records':'进度记录'} <b>${summary.progress}</b></span></div></div>`)}applyUiLanguage()};
const studyAgentFetch = window.fetch.bind(window);
window.fetch = (input, init = {}) => {
  const url = typeof input === 'string' ? input : input?.url || '';
  if (S.learningSessionId && typeof init.body === 'string' && (/\/api\/chat(?:\/stream)?$/.test(url) || /\/api\/documents\/[^/]+\/annotations$/.test(url))) {
    try { const payload = JSON.parse(init.body); if (!payload.sessionId) { payload.sessionId = S.learningSessionId; init = { ...init, body: JSON.stringify(payload) }; } } catch { /* non-JSON requests are passed through */ }
  }
  return studyAgentFetch(input, init);
};
const studyAgentReader = reader;
reader = function(){ const result = studyAgentReader(); if(S.route==='reading'){ const groups=document.querySelectorAll('.viewer-toolbar .toolbar-group'); const target=groups[groups.length-1]; if(target&&!document.getElementById('finish-learning-session')) target.insertAdjacentHTML('beforeend','<button id="finish-learning-session" class="tiny-btn" onclick="finishLearningSession()">结束学习</button>'); } return result; };

// Prefer the request/response path for reader questions.  It is supported by
// every configured provider, while the optional SSE path can be blocked by a
// local proxy or leave the reader waiting after only its initial status event.
send = async function(id){
  const settings = await ensurePromptSettings();
  if (settings.showPreview && !S.pendingPromptOverride) {
    const input = document.getElementById(id); const text = input?.value.trim();
    if (!text) return;
    const config = currentModelConfig();
    const body = { message: text, documentId: S.doc?.id, page: S.p, selectedText: S.selection, formula: S.selectionLatex || undefined, language: S.settings.language === 'en' ? 'en' : 'zh', scope: document.getElementById('learning-scope')?.value || 'current-document', courseId: document.getElementById('learning-course')?.value || undefined, documentIds: Array.from(document.getElementById('learning-documents')?.selectedOptions || []).map(option => option.value), remember: document.getElementById('learning-remember')?.checked !== false, conversationId: S.conversationId || undefined, configId: config.id || undefined };
    try { const preview = await api('/api/prompt/optimize', { method: 'POST', body: JSON.stringify(body) }); S.pendingPrompt = { inputId: id, body, preview }; renderPromptPreview(preview); } catch (error) { toast(error.message); }
    return;
  }
  const input = document.getElementById(id); const text = input?.value.trim();
  if (!text) return;
  const config = currentModelConfig();
  const body = { message: text, documentId: S.doc?.id, page: S.p, selectedText: S.selection, formula: S.selectionLatex || undefined, language: S.settings.language === 'en' ? 'en' : 'zh', scope: document.getElementById('learning-scope')?.value || 'current-document', courseId: document.getElementById('learning-course')?.value || undefined, documentIds: Array.from(document.getElementById('learning-documents')?.selectedOptions || []).map(option => option.value), remember: document.getElementById('learning-remember')?.checked !== false, conversationId: S.conversationId || undefined, configId: config.id || undefined };
  input.value = '';
  const assistant = { role: 'assistant', text: '', provider: config.provider || 'local', model: config.model || 'Evidence-first local mode', citations: [], memoryAssociations: [] };
  S.messages.push({ role: 'user', text, selectedText: S.selection, citations: [] }, assistant);
  if (S.route === 'reading') reader(); else render();
  try {
    const result = await api('/api/chat', { method: 'POST', body: JSON.stringify(body) });
    S.conversationId = result.conversationId || S.conversationId;
    assistant.text = result.answer; assistant.citations = result.citations || []; assistant.memoryAssociations = result.memoryAssociations || [];
    assistant.provider = result.provider; assistant.model = result.model;
  } catch (error) { assistant.text = error.message; toast(error.message); }
  if (S.route === 'reading') reader(); else render();
};
